Object.assign(window.TEM8_DICTIONARY, {"arrangements":{"oxford":{"phon":"əˈreɪndʒmənt","pos":"noun","senses":[{"en":"a plan or preparation that you make so that sth can happen","cn":"安排；筹备"},{"en":"the way things are done or organized","cn":"安排方式；布置"}]}},"artifact":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/artifact__gb_1.mp3","us":"media/us/artifact__us_1.mp3"},"oxford":{"phon":"ˈɑːtɪfækt","pos":"noun","senses":[{"en":"an object that is made by a person, especially something of historical or cultural interest","cn":"人工制品，手工艺品（尤指有历史或文化价值的）"}]}},"are":{"media":{"uk":"media/uk/are__gb_1.mp3","us":"media/us/are__us_1.mp3"},"oxford":{"phon":"eə(r)","pos":"noun","senses":[{"en":"a unit for measuring an area of land; 100 square metres","cn":"公亩（等于 100 平方米）"}]},"collins":{"senses":[{"pos":"","cn":"（be的复数和第二人称单数现在时形式，口语中在代词后常略作-’re）","en":"Are is the plural and the second person singular of the present tense of the verb be .Are is often shortened to -'re after pronouns in spoken English."}]}},"artistic":{"media":{"uk":"media/uk/artistic__gb_1.mp3","us":"media/us/artistic__us_1.mp3"},"oxford":{"phon":"ɑːˈtɪstɪk","pos":"adjective","senses":[{"en":"connected with art or artists","cn":"艺术的；艺术家的","ex":{"en":"the artistic works of the period","cn":"该时期的艺术品"}},{"en":"showing a natural skill or pleasure in art, especially being able to paint or draw well","cn":"有艺术天赋的；（尤指）有美术才能的","ex":{"en":"artistic abilities/achievements/skills/talent","cn":"艺术才能／成就／技巧／天才"}},{"en":"done with skill and imagination; attractive or beautiful","cn":"有艺术性的；精美的","ex":{"en":"an artistic arrangement of dried flowers","cn":"富有艺术性的干花插花"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有艺术天赋的;有艺术鉴赏力的","en":"Someone who is artistic is good at drawing or painting, or arranging things in a beautiful way.","ex":{"en":"They encourage boys to be sensitive and artistic","cn":"他们鼓励培养男孩子的敏感和艺术气质。"}},{"pos":"ADJ 形容词","cn":"艺术的;艺术家的","en":"Artistic means relating to art or artists.","ex":{"en":"...the campaign for artistic freedom.","cn":"艺术自由运动"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精美的；富有艺术性的","en":"An artistic design or arrangement is beautiful.","ex":{"en":"...an artistic arrangement of stone paving.","cn":"石子路的精美图案"}}]},"examples":[{"en":"an artistic arrangement of dried flowers","cn":"富有艺术性的干花插花"},{"en":"a work of great artistic merit","cn":"艺术价值很高的作品"}]},"argument":{"media":{"uk":"media/uk/argument__gb_1.mp3","us":"media/us/argument__us_1.mp3","img":["media/ldoce/img/argument.jpg"]},"oxford":{"phon":"ˈɑːɡjumənt","pos":"noun","senses":[{"en":"a conversation or discussion in which two or more people disagree, often angrily","cn":"争论；争吵；争辩；辩论","g":"[countable, uncountable]","ex":{"en":"to win/lose an argument","cn":"辩论赢了／输了"}},{"en":"a reason or set of reasons that somebody uses to show that something is true or correct","cn":"论据；理由；论点","g":"[countable]","ex":{"en":"a strong/convincing/compelling argument","cn":"有力的／令人信服的／有说服力的论据"}},{"en":"the act of disagreeing in a conversation or discussion using a reason or set of reasons","cn":"辩论","g":"[uncountable]","ex":{"en":"Let's assume for the sake of argument (= in order to discuss the problem) that we can't start till March.","cn":"为方便讨论起见，先假定我们要到三月份才能开始。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"理由；论据；论点","en":"An argument is a statement or set of statements that you use in order to try to convince people that your opinion about something is correct.","ex":{"en":"There's a strong argument for lowering the price","cn":"有充分理由要求降低价格。"}},{"pos":"N-VAR 可变名词","cn":"讨论；辩论","en":"An argument is a discussion or debate in which a number of people put forward different or opposing opinions.","ex":{"en":"The incident has triggered fresh arguments about the role of the extreme right in France","cn":"该事件引发了关于极右翼势力在法国所起作用的新一轮讨论。"}},{"pos":"N-COUNT 可数名词","cn":"争论；争执；争吵","en":"An argument is a conversation in which people disagree with each other angrily or noisily.","ex":{"en":"Anny described how she got into an argument with one of the marchers.","cn":"安妮描述了她是如何与其中一位游行者发生争执的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"异议；质疑","en":"If you accept something without argument, you do not question it or disagree with it.","ex":{"en":"He complied without argument","cn":"他二话不说就服从了。"}}]},"examples":[{"en":"Let's assume for the sake of argument (= in order to discuss the problem) that we can't start till March.","cn":"为方便讨论起见，先假定我们要到三月份才能开始。"},{"en":"There are strong arguments for and against euthanasia.","cn":"对安乐死支持和反对的人都有强而有力的论据。"}]},"arranging":{"oxford":{"phon":"əˈreɪndʒ","pos":"verb","senses":[{"en":"to plan or organize sth in advance","cn":"安排；筹备"},{"en":"to put sth in a particular order; to make sth neat or attractive","cn":"整理；排列；布置"}]}},"arrogant":{"media":{"uk":"media/uk/arrogant__gb_1.mp3","us":"media/us/arrogant__us_1.mp3"},"oxford":{"phon":"ˈærəɡənt","pos":"adjective","senses":[{"en":"behaving in a proud, unpleasant way, showing little thought for other people","cn":"傲慢的；自大的","ex":{"en":"He was a rude, arrogant young man.","cn":"他是个不懂礼貌、目中无人的年轻人。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"傲慢的;自大的;嚣张的","en":"Someone who is arrogant behaves in a proud, unpleasant way towards other people because they believe that they are more important than others.","ex":{"en":"He was so arrogant","cn":"他是如此傲慢。"}}]},"examples":[{"en":"He was unbearably arrogant.","cn":"他的傲慢让人无法忍受。"},{"en":"an arrogant attitude","cn":"傲慢的态度"}]},"artist":{"media":{"uk":"media/uk/artist__gb_1.mp3","us":"media/us/artist__us_1.mp3","img":["media/ldoce/img/canvas.jpg"]},"oxford":{"phon":"ˈɑːtɪst","pos":"noun","senses":[{"en":"a person who creates works of art, especially paintings or drawings","cn":"艺术家；（尤指）画家","lab":"figurative","ex":{"en":"an exhibition of work by contemporary British artists","cn":"当代英国画家作品展"}},{"en":"a person who is a professional singer, dancer, actor, etc.","cn":"艺术家（指职业歌手、舞蹈家、演员等）","ex":{"en":"a recording/solo artist","cn":"音像录制艺术师；单人表演演员"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"画家;雕塑家;艺术家","en":"An artist is someone who draws or paints pictures or creates sculptures as a job or a hobby.","ex":{"en":"...the studio of a great artist","cn":"一个伟大的艺术家的工作室"}},{"pos":"N-COUNT 可数名词","cn":"艺术家（如小说家、诗人、导演等）","en":"An artist is a person who creates novels, poems, films, or other things which can be considered as works of art.","ex":{"en":"His books are enormously easy to read, yet he is a serious artist","cn":"虽然他是一个不折不扣的艺术家，但是他的作品极其通俗易懂。"}},{"pos":"N-COUNT 可数名词","cn":"表演艺术家;艺人","en":"An artist is a performer such as a musician, actor, or dancer.","ex":{"en":"...a popular artist who has sold millions of records.","cn":"唱片销量达到数百万张的当红音乐家"}},{"pos":"N-COUNT 可数名词","cn":"能手;高手;大师","en":"If you say that someone is an artist at a particular activity, you mean they are very skilled at it.","ex":{"en":"He is an exceptional footballer — an artist.","cn":"他是一名出色的足球运动员，一个足球高手。"}}]},"examples":[{"en":"( figurative ) Whoever made this cake is a real artist.","cn":"制作这个蛋糕的人真是个艺术大师。"},{"en":"Police have issued an artist's impression of her attacker.","cn":"警方公布了袭击她的人的模拟像。"}]},"arose":{"collins":{"senses":[{"pos":"","cn":"","en":"Arose is the past tense of arise."}]},"media":{"uk":"media/uk/arose__gb_1.mp3","us":"media/us/arose__us_1.mp3"}},"argue":{"media":{"uk":"media/uk/argue__gb_1.mp3","us":"media/us/argue__us_1.mp3"},"oxford":{"phon":"ˈɑːɡjuː","pos":"verb","senses":[{"en":"to speak angrily to somebody because you disagree with them","cn":"争论；争吵；争辩","g":"[intransitive]","ex":{"en":"My brothers are always arguing.","cn":"我的兄弟们总是争论不休。"}},{"en":"to give reasons why you think that something is right/wrong, true/not true, etc., especially to persuade people that you are right","cn":"论证；说理；争辩","g":"[intransitive, transitive]","ex":{"en":"They argued for the right to strike.","cn":"他们据理力争罢工权利。"}},{"en":"to show clearly that something exists or is true","cn":"证明；表明","g":"[transitive]","lab":"formal","ex":{"en":"These latest developments argue a change in government policy.","cn":"最近的事态发展表明政府改变了政策。"}}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"争吵;争执","en":"If one person argues with another, they speak angrily to each other about something that they disagree about. You can also say that two people argue .","ex":{"en":"The committee is concerned about players' behaviour, especially arguing with referees","cn":"委员会很关注运动员的行为，特别是与裁判争吵的行为。"}},{"pos":"VERB 动词","cn":"争论；争辩","en":"If you tell someone not to argue with you, you want them to do or believe what you say without protest or disagreement.","ex":{"en":"Don't argue with me","cn":"别和我争辩。"}},{"pos":"V-RECIP 相互动词","cn":"辩论；讨论","en":"If you argue with someone about something, you discuss it with them, with each of you giving your different opinions.","ex":{"en":"He was arguing with the King about the need to maintain the cavalry at full strength","cn":"他正和国王讨论保留骑兵全部力量的必要性。"}},{"pos":"VERB 动词","cn":"主张；认为","en":"If you argue that something is true, you state it and give the reasons why you think it is true.","ex":{"en":"His lawyers are arguing that he is unfit to stand trial","cn":"他的律师正在提出理由说明他不适合出庭受审。"}},{"pos":"VERB 动词","cn":"支持/反对","en":"If you argue for something, you say why you agree with it, in order to persuade people that it is right. If you argue against something, you say why you disagree with it, in order to persuade people that it is wrong.","ex":{"en":"The report argues against tax increases","cn":"报告提出理由反对提高税率。"}},{"pos":"VERB 动词","cn":"论证;说理;争辩","en":"If you argue, you support your opinions with evidence in an ordered or logical way.","ex":{"en":"I've argued deductively from the text","cn":"我已依文字作过推理论证。"}},{"pos":"VERB 动词","cn":"不承认;对…有争议","en":"If you say that no-one can argue with a particular fact or opinion, you are emphasizing that it is obviously true and so everyone must accept it.","ex":{"en":"We produced the best soccer of the tournament. Nobody would argue with that.","cn":"本届比赛中我们踢出了最漂亮的足球，谁都不会否认这一点。"}},{"pos":"","cn":"","en":"to argue the toss→see: ;"},{"pos":"","cn":"","en":"相关词组：argue out"}]},"examples":[{"en":"He argued that they needed more time to finish the project.","cn":"他提出理由说明他们需要更多的时间来完成该项目。"},{"en":"It could be argued that laws are made by and for men.","cn":"法律由人制订，也是为人制订的这一点颇有道理。"}]},"arrest":{"oxford":{"phon":"əˈrest","pos":"verb","senses":[{"en":"if the police arrest somebody, the person is taken to a police station and kept there because the police believe they may be guilty of a crime","cn":"逮捕；拘留","g":"[transitive, often passive]","lab":"especially North American English","ex":{"en":"A man has been arrested in connection with the robbery.","cn":"一名男子因与这桩抢劫案有关已被逮捕。"}},{"en":"to stop a process or a development","cn":"阻止；中止","g":"[transitive]","lab":"formal","ex":{"en":"They failed to arrest the company's decline.","cn":"他们未能阻止公司的衰落。"}},{"en":"to make somebody notice something and pay attention to it","cn":"吸引（注意）","g":"[transitive]","lab":"formal","ex":{"en":"An unusual noise arrested his attention.","cn":"一阵不寻常的嘈杂声引起了他的注意。"}},{"en":"if somebody arrests, their heart stops beating","cn":"心跳停止","g":"[intransitive]","lab":"medical","ex":{"en":"He arrested on the way to the hospital.","cn":"他在送医院途中停止了心跳。"}},{"en":"the act of arresting somebody","cn":"逮捕；拘捕","ex":{"en":"The police made several arrests.","cn":"警方逮捕了好几人。"},"pos":"noun"},{"en":"an act of something stopping or being interrupted","cn":"停止；中止","ex":{"en":"He died after suffering a cardiac arrest (= when his heart suddenly stopped).","cn":"他死于心脏停搏。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"逮捕;拘捕;拘留","en":"If the police arrest you, they take charge of you and take you to a police station, because they believe you may have committed a crime.","ex":{"en":"Police arrested five young men in connection with one of the attacks","cn":"警方逮捕了与其中一次袭击有关的5名青年男子。"}},{"pos":"VERB 动词","cn":"阻止;抑制","en":"If something or someone arrests a process, they stop it continuing.","ex":{"en":"The sufferer may have to make major changes in his or her life to arrest the disease","cn":"患者可能必须对生活习惯作出重大调整以控制病情。"}},{"pos":"VERB 动词","cn":"吸引（注意）","en":"If something interesting or surprising arrests your attention, you suddenly notice it and then continue to look at it or consider it carefully.","ex":{"en":"The work of an architect of genius always arrests the attention no matter how little remains","cn":"天才建筑师的作品无论残留多少都能最大限度地吸引眼球。"}}]},"media":{"uk":"media/uk/arrest__gb_1.mp3","us":"media/us/arrest__us_1.mp3","img":["media/ldoce/img/arrest.jpg"]},"examples":[{"en":"A man has been arrested in connection with the robbery.","cn":"一名男子因与这桩抢劫案有关已被逮捕。"},{"en":"An unusual noise arrested his attention.","cn":"一阵不寻常的嘈杂声引起了他的注意。"}]},"artificially":{"oxford":{"phon":"ˌɑːtɪˈfɪʃəli","pos":"adverb","senses":[{"en":"in a way that copies something natural","cn":"人工地，人造地","ex":{"en":"artificially created lakes","cn":"人工湖泊"}},{"en":"in a way that has been caused by people rather than existing or happening naturally","cn":"人为地，非自然地","ex":{"en":"artificially low prices","cn":"人为造成的低价"}}]},"media":{"uk":"media/uk/artificially__gb_1.mp3","us":"media/us/artificially__us_1.mp3"},"examples":[{"en":"artificially low prices","cn":"人为压低的价格"},{"en":"artificially created lakes","cn":"人工湖泊"}]},"articulated":{"media":{"img":["media/pic/trucks_comp.jpg","media/thumb/articulatedlorry.jpg"],"uk":"media/uk/articulated__gb_1.mp3","us":"media/us/articulated__us_1.mp3"},"oxford":{"phon":"ɑːˈtɪkjuleɪtɪd","pos":"adjective","senses":[{"en":"with two or more sections joined together in a way that makes it easier to turn corners","cn":"铰接的","ex":{"en":"an articulated lorry/truck","cn":"铰接式卡车"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（尤指卡车）铰接式的","en":"An articulated vehicle, especially a lorry, is made in two or more sections which are joined together by metal bars, so that the vehicle can turn more easily."}]},"examples":[{"en":"an articulated lorry/truck","cn":"铰接式卡车"}]},"archbishop":{"oxford":{"phon":"ˌɑːtʃˈbɪʃəp","pos":"noun","senses":[{"en":"a bishop of the highest rank, responsible for all the churches in a large area","cn":"大主教；总主教","ex":{"en":"the Archbishop of Canterbury (= the head of the Church of England)","cn":"坎特伯雷大主教（即英国国教会领袖）"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"（天主教、东正教和英国国教的）大主教，主教长","en":"In the Roman Catholic, Orthodox, and Anglican Churches, an archbishop is a bishop of the highest rank, who is in charge of all the bishops and priests in a particular country or region.","ex":{"en":"...the Archbishop of Canterbury.","cn":"坎特伯雷大主教"}}]},"media":{"uk":"media/uk/archbishop__gb_1.mp3","us":"media/us/archbishop__us_1.mp3"},"examples":[{"en":"the Archbishop of Canterbury (= the head of the Church of England)","cn":"坎特伯雷大主教（即英国国教会领袖）"}]},"architecture":{"media":{"img":["media/pic/architecture_comp.jpg","media/thumb/arch.jpg"],"uk":"media/uk/architecture__gb_1.mp3","us":"media/us/architecture__us_1.mp3"},"oxford":{"phon":"ˈɑːkɪtektʃə(r)","pos":"noun","senses":[{"en":"the art and study of designing buildings","cn":"建筑学","g":"[uncountable]","ex":{"en":"to study architecture","cn":"学习建筑学"}},{"en":"the design or style of a building or buildings","cn":"建筑设计；建筑风格","g":"[uncountable]","ex":{"en":"the architecture of the eighteenth century","cn":"十八世纪的建筑风格"}},{"en":"the design and structure of a computer system","cn":"体系结构；（总体、层次）结构，架构","g":"[countable, uncountable]","lab":"computing"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"建筑学;建筑术","en":"Architecture is the art of planning, designing, and constructing buildings.","ex":{"en":"He studied classical architecture and design in Rome.","cn":"他在罗马学习了古典建筑学和设计。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"建筑式样；建筑风格","en":"The architecture of a building is the style in which it is designed and constructed.","ex":{"en":"...modern architecture.","cn":"现代建筑式样"}},{"pos":"N-UNCOUNT 不可数名词","cn":"结构;架构","en":"The architecture of something is its structure.","ex":{"en":"...the crumbling intellectual architecture of modern society.","cn":"现代社会处于崩溃边缘的知识结构"}}]},"examples":[{"en":"the architecture of the eighteenth century","cn":"十八世纪的建筑风格"},{"en":"modern architecture","cn":"现代建筑设计"}]},"arrow":{"oxford":{"phon":"ˈærəʊ","pos":"noun","senses":[{"en":"a thin stick with a sharp point at one end, which is shot from a bow","cn":"箭","ex":{"en":"a bow and arrow","cn":"弓箭"}},{"en":"a mark or sign like an arrow (➞), used to show direction or position","cn":"箭号；箭头","ex":{"en":"Follow the arrows.","cn":"顺着箭头指示方向走。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"箭；矢","en":"An arrow is a long thin weapon which is sharp and pointed at one end and which often has feathers at the other end. An arrow is shot from a bow.","ex":{"en":"Warriors armed with bows and arrows and spears have invaded their villages.","cn":"佩带弓箭和长矛的武士闯入了他们的村庄。"}},{"pos":"N-COUNT 可数名词","cn":"箭头（用来指示方向，符号为→）","en":"An arrow is a written or printed sign that consists of a straight line with another line bent at a sharp angle at one end. This is a printed arrow: →. The arrow points in a particular direction to indicate where something is.","ex":{"en":"A series of arrows points the way to the modest grave of Andrei Sakharov.","cn":"一连串的箭头指示着通往安德烈·萨哈罗夫的朴素的墓地的路。"}},{"pos":"","cn":"","en":"slings and arrows→see: ;"}]},"media":{"uk":"media/uk/arrow__gb_1.mp3","us":"media/us/arrow__us_1.mp3"},"examples":[{"en":"Use the arrow keys to move the cursor.","cn":"用键盘上的箭头键移动光标。"},{"en":"Follow the arrows.","cn":"顺着箭头指示方向走。"}]},"arranged":{"oxford":{"phon":"əˈreɪndʒ","pos":"verb","senses":[{"en":"to plan or organize sth in advance","cn":"安排；筹备"},{"en":"to put sth in a particular order; to make sth neat or attractive","cn":"整理；排列；布置"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"安置于…的;建于…的;…布置的","en":"If you say how things are arranged, you are talking about their position in relation to each other or to something else.","ex":{"en":"The house itself is three stories high and arranged around a courtyard","cn":"房子本身有三层高，绕着一个庭院而建。"}}]}},"art":{"media":{"uk":"media/uk/art__gb_1.mp3","us":"media/us/art__us_1.mp3"},"oxford":{"phon":"ɑːt","pos":"noun","senses":[{"en":"the use of the imagination to express ideas or feelings, particularly in painting, drawing or sculpture","cn":"艺术，美术（特指绘画、雕刻、雕塑）","g":"[uncountable]","ex":{"en":"modern/contemporary art","cn":"现代／当代艺术"}},{"en":"examples of objects such as paintings, drawings or sculptures","cn":"艺术作品；美术作品","g":"[uncountable]","ex":{"en":"an art gallery/exhibition","cn":"美术馆；美术展览"}},{"en":"the skill of creating objects such as paintings and drawings, especially when you study it","cn":"艺术技巧","g":"[uncountable]","lab":"US English","ex":{"en":"She's good at art and design.","cn":"她擅长美术和设计。"}},{"en":"art, music, theatre, literature, etc. when you think of them as a group","cn":"（统称）艺术","g":"[plural]","ex":{"en":"lottery funding for the arts","cn":"为艺术筹集资金的彩票"}},{"en":"a type of visual or performing art","cn":"表演艺术","g":"[countable]","ex":{"en":"an exhibition of Peruvian arts and crafts","cn":"秘鲁工艺品展"}},{"en":"the subjects you can study at school or university that are not sciences, such as languages, history or literature","cn":"人文科学，文科（如语言、历史、文学）","g":"[countable, usually plural]","ex":{"en":"an arts degree","cn":"文科学位"}},{"en":"an ability or a skill that you can develop with training and practice","cn":"技能；技术；技巧","g":"[countable, uncountable]","ex":{"en":"a therapist trained in the art of healing","cn":"接受过治疗技术训练的治疗员"}},{"en":"used to mean ‘you are’, when talking to one person","cn":"（即 you are，对一人讲话时用）","pos":"verb"},{"en":"a first name for boys, sometimes short for Arthur","cn":"阿特（男子名，有时为 Arthur 缩写）","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"艺术（品）；美术","en":"Art consists of paintings, sculpture, and other pictures or objects which are created for people to look at and admire or think deeply about.","ex":{"en":"...the first exhibition of such art in the West.","cn":"此类艺术品在西方的首次展览"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（作为活动或教学科目的）美术","en":"Art is the activity or educational subject that consists of creating paintings, sculptures, and other pictures or objects for people to look at and admire or think deeply about.","ex":{"en":"...a painter, content to be left alone with her all-absorbing art.","cn":"甘愿独自沉浸于绘画中的画家"}},{"pos":"N-VAR 可变名词","cn":"艺术（活动）（如音乐、绘画、文学、电影、舞蹈等）","en":"The arts are activities such as music, painting, literature, cinema, and dance, which people can take part in for enjoyment, or to create works which express serious meanings or ideas of beauty.","ex":{"en":"Catherine the Great was a patron of the arts and sciences.","cn":"叶卡捷琳娜大帝赞助过各种艺术创作和科学研究。"}},{"pos":"N-PLURAL 复数名词","cn":"人文学科;文科","en":"At a university or college, arts are subjects such as history, literature, or languages in contrast to scientific subjects.","ex":{"en":"...arts and social science graduates.","cn":"人文和社会科学毕业生"}},{"pos":"ADJ 形容词","cn":"（用于剧院或电影院的名称中）上演艺术作品的，艺术的","en":"Arts or art is used in the names of theatres or cinemas which show plays or films that are intended to make the audience think deeply about the content, and not simply to entertain them.","ex":{"en":"...the Cambridge Arts Cinema.","cn":"剑桥艺术影院"}},{"pos":"N-COUNT 可数名词","cn":"技术；技艺；技巧","en":"If you describe an activity as an art, you mean that it requires skill and that people learn to do it by instinct or experience, rather than by learning facts or rules.","ex":{"en":"Fishing is an art.","cn":"钓鱼是一门技术。"}},{"pos":"","cn":"（be的现在式单数第二人称形式，过时用法）","en":"Art is an old-fashioned form of the second person singular of the present tense of the verb be.","ex":{"en":"Father, I know thou art aware of me at all times.","cn":"父亲，我知道您无时无刻不在关心着我。"}}]},"examples":[{"en":"Appearing confident at interviews is quite an art (= rather difficult).","cn":"面试时表现出充满信心是一门很高的艺术。"},{"en":"Dance is a very theatrical art.","cn":"舞蹈是非常讲究舞台感的一种艺术。"}]},"archaeology":{"media":{"uk":"media/uk/archaeology__gb_1.mp3","us":"media/us/archaeology__us_1.mp3"},"oxford":{"phon":"ˌɑːkiˈɒlədʒi","pos":"noun","senses":[{"en":"the study of cultures of the past, and of periods of history by examining the parts of buildings and objects found in the ground","cn":"考古学"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"考古学","en":"Archaeology is the study of the societies and peoples of the past by examining the remains of their buildings, tools, and other objects."}]},"examples":[{"en":"archaeological excavations/evidence","cn":"考古发掘/实证"}]},"arc":{"oxford":{"phon":"ɑːk","pos":"noun","senses":[{"en":"a curved line that is part of a circle","cn":"弧","lab":"geometry","ex":{"en":"to draw an arc using a compass","cn":"使用圆规绘制圆弧"}},{"en":"a curved shape","cn":"弧形","ex":{"en":"the arc of a rainbow","cn":"彩虹的弧形"}},{"en":"the basic story, the story of one character or the main theme in a novel, film, etc.","cn":"（小说、电影等的）主线，情节","ex":{"en":"The vivid characters and the satisfying story arc make this a rewarding novel.","cn":"这部小说人物生动，故事情节感人，值得一读。"}},{"en":"an electric current passing across a space between two terminals","cn":"电弧","lab":"specialist"},{"en":"to move in the shape of an arc","cn":"做弧形运动","g":"[intransitive]","ex":{"en":"For a few seconds a perfect rainbow arced across the city.","cn":"一道完美的彩虹呈弧状架在城市之上数秒钟。"},"pos":"verb"},{"en":"to form an electric arc","cn":"形成电弧","g":"[intransitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"弧形；弧线","en":"An arc is a smoothly curving line or movement.","ex":{"en":"The Aleutian chain is a long arc of islands in the North Pacific.","cn":"阿留申群岛是北太平洋上一长串呈弧形排列的小岛。"}},{"pos":"N-COUNT 可数名词","cn":"弧","en":"In geometry, an arc is a part of the line that forms the outside of a circle."},{"pos":"VERB 动词","cn":"成弧线；呈弧形","en":"If something arcs in a particular direction, it makes a smoothly curving line or movement.","ex":{"en":"A rainbow arced gracefully over the town.","cn":"彩虹在小城上空画出了一道优美的弧线。"}}]},"media":{"img":["media/pic/circles_comp.jpg","media/thumb/circles2.jpg"],"uk":"media/uk/arc__gb_1.mp3","us":"media/us/arc__us_1.mp3"},"examples":[{"en":"The beach swept around in an arc.","cn":"海滩呈弧形伸展开来。"},{"en":"the arc of a rainbow","cn":"彩虹的弧形"}]},"arctic":{"media":{"uk":"media/uk/arctic__gb_1.mp3","us":"media/us/arctic__us_1.mp3"},"oxford":{"phon":"ˈɑːktɪk","pos":"adjective","senses":[{"en":"related to or happening in the regions around the North Pole","cn":"北极的；北极地区的","g":"[only before noun]","ex":{"en":"Arctic explorers","cn":"北极探险者"}},{"en":"extremely cold","cn":"极冷的；严寒的","ex":{"en":"TV pictures showed the arctic conditions.","cn":"电视画面显示了严寒的环境。"}},{"en":"the regions of the world around the North Pole","cn":"北极；北极地区","pos":"noun"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"北极；北极地区","en":"The Arctic is the area of the world around the North Pole. It is extremely cold and there is very little light in winter and very little darkness in summer.","ex":{"en":"...winter in the Arctic.","cn":"北极的冬天"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极冷的；严寒的","en":"If you describe a place or the weather as arctic, you are emphasizing that it is extremely cold.","ex":{"en":"The bathroom, with its ancient facilities, is positively arctic.","cn":"该浴室设备陈旧，肯定非常寒冷。"}}]},"examples":[{"en":"TV pictures showed the arctic conditions.","cn":"电视画面显示了严寒的环境。"},{"en":"Arctic explorers","cn":"北极探险者"}]},"army":{"media":{"uk":"media/uk/army__gb_1.mp3","us":"media/us/army__us_1.mp3"},"oxford":{"phon":"ˈɑːmi","pos":"noun","senses":[{"en":"a large organized group of soldiers who are trained to fight on land","cn":"陆上作战军队；陆军部队","g":"[countable + singular or plural verb]","ex":{"en":"The two opposing armies faced each other across the battlefield.","cn":"敌对两军在战场上严阵对峙。"}},{"en":"the part of a country’s armed forces that fights on land","cn":"（一国的）陆军","g":"[singular + singular or plural verb]","ex":{"en":"Her sister is in the army.","cn":"她的姐姐在部队里。"}},{"en":"a large number of people or things, especially when they are organized in some way or involved in a particular activity","cn":"大批；大群","g":"[countable + singular or plural verb]","ex":{"en":"an army of advisers/volunteers","cn":"一大批顾问；志愿者大军"}}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"陆军;陆军部队","en":"An army is a large organized group of people who are armed and trained to fight on land in a war. Most armies are organized and controlled by governments.","ex":{"en":"After returning from France, he joined the army","cn":"从法国回来之后，他参了军。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"大批;大群","en":"An army of people, animals, or things is a large number of them, especially when they are regarded as a force of some kind.","ex":{"en":"...data collected by an army of volunteers.","cn":"由大批志愿者收集的资料"}}]},"examples":[{"en":"An army of ants marched across the path.","cn":"一大群蚂蚁浩浩荡荡地穿过小径。"},{"en":"After leaving school, Mike went into the army.","cn":"迈克在学校毕业后参加了陆军。"}]},"archives":{"oxford":{"phon":"ˈɑːkaɪv","pos":"noun","senses":[{"en":"a collection of historical documents or records of a government, a family, a place or an organization; the place where these records are stored","cn":"档案；档案馆；档案室"},{"en":"to put or store a document or other material in an archive","cn":"把 … 存档；把 … 归档"}]}},"artificial":{"media":{"uk":"media/uk/artificial__gb_1.mp3","us":"media/us/artificial__us_1.mp3"},"oxford":{"phon":"ˌɑːtɪˈfɪʃl","pos":"adjective","senses":[{"en":"made or produced to copy something natural; not real","cn":"人工的；人造的；假的","ex":{"en":"an artificial limb/flower/sweetener/fertilizer","cn":"假肢；假花；人造甜味剂；化肥"}},{"en":"created by people; not happening naturally","cn":"人为的；非自然的","ex":{"en":"A job interview is a very artificial situation.","cn":"求职面试是一个相当不自然的场面。"}},{"en":"not what it appears to be","cn":"虚假的；假装的","ex":{"en":"artificial emotion","cn":"假装的情感"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"人造的；非自然形成的","en":"Artificial objects, materials, or processes do not occur naturally and are created by human beings, for example using science or technology.","ex":{"en":"...a wholefood diet free from artificial additives, colours and flavours","cn":"不含人工添加剂、色素和香料的天然食品"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"人造的；不自然的；假的","en":"An artificial state or situation exists only because someone has created it, and therefore often seems unnatural or unnecessary.","ex":{"en":"Even in the artificial environment of an office, our body rhythms continue to affect us","cn":"即使是在办公室这样的非自然环境中，我们的人体生物钟依然影响着我们。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"假装的；虚伪的；矫揉造作的","en":"If you describe someone or their behaviour as artificial, you disapprove of them because they pretend to have attitudes and feelings which they do not really have.","ex":{"en":"The voice was patronizing and affected, the accent artificial.","cn":"声音拿腔拿调的，听上去矫揉造作。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（味道、外观）不自然的，不真实的，添加非天然成分的","en":"If you say that food tastes or looks artificial, you do not like it because its taste or appearance does not seem genuine, and seems to be created by added substances.","ex":{"en":"The meat was chewy and the sauce was glutinous and tasted artificial.","cn":"肉嚼不烂，酱汁黏稠，味道也不自然。"}}]},"examples":[{"en":"A job interview is a very artificial situation.","cn":"求职面试是一个相当不自然的场面。"},{"en":"the artificial barriers of race, class and gender","cn":"种族、阶级、性别的人为障碍"}]},"arithmetic":{"oxford":{"phon":"əˈrɪθmətɪk","pos":"noun","senses":[{"en":"the type of mathematics that deals with the adding, multiplying, etc. of numbers","cn":"算术","ex":{"en":"He's not very good at arithmetic.","cn":"他不太擅长算术。"}},{"en":"sums involving the adding, multiplying, etc. of numbers","cn":"算术运算；四则运算","ex":{"en":"a quick bit of mental arithmetic (= sums you do in your head, without writing anything down)","cn":"快速心算"}},{"en":"relating to arithmetic","cn":"算术的","ex":{"en":"arithmetic calculation","cn":"算术计算"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"算术","en":"Arithmetic is the part of mathematics that is concerned with the addition, subtraction, multiplication, and division of numbers.","ex":{"en":"...teaching the basics of reading, writing and arithmetic.","cn":"教授阅读、写作和算术的基础知识"}},{"pos":"N-UNCOUNT 不可数名词","cn":"演算；计算","en":"You can use arithmetic to refer to the process of doing a particular sum or calculation.","ex":{"en":"4,000 women put in ten rupees each, which if my arithmetic is right adds up to 40,000 rupees.","cn":"4,000名妇女每人放入10个卢比，如果我算得对的话，总数将达到4万卢比。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（某形势的）数据统计","en":"If you refer to the arithmetic of a situation, you are concerned with those aspects of it that can be expressed in numbers, and how they affect the situation.","ex":{"en":"The budgetary arithmetic suggests that government borrowing is set to surge","cn":"预算数字表明政府借款将要大幅增加。"}},{"pos":"ADJ 形容词","cn":"算术的;运算的","en":"Arithmetic means relating to or consisting of calculations involving numbers.","ex":{"en":"...a processor which performs simple arithmetic operations such as adding or multiplying numbers.","cn":"可进行加法或乘法等简单运算的处理器"}}]},"media":{"uk":"media/uk/arithmetic__gb_1.mp3","us":"media/us/arithmetic__us_1.mp3"},"examples":[{"en":"I think there's something wrong with your arithmetic.","cn":"我认为你的计算有错。"},{"en":"He's not very good at arithmetic.","cn":"他不太擅长算术。"}]},"archaeological":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the study of ancient societies by examining what remains of their buildings, grave s , tools etc","cn":""}]},"media":{"uk":"media/uk/archaeological__gb_1.mp3","us":"media/us/archaeological__us_1.mp3"},"oxford":{"phon":"ˌɑːkiəˈlɒdʒɪkl","pos":"adjective","senses":[{"en":"connected with the study of cultures of the past and of periods of history by examining the parts of buildings and objects found in the ground","cn":"考古的；考古学的","ex":{"en":"archaeological excavations/evidence","cn":"考古发掘／证据"}}]}},"archive":{"oxford":{"phon":"ˈɑːkaɪv","pos":"noun","senses":[{"en":"a collection of historical documents or records of a government, a family, a place or an organization; the place where these records are stored","cn":"档案；档案馆；档案室","ex":{"en":"the National Sound Archive","cn":"国家音响档案馆"}},{"en":"an electronic record of the data on a computer system, stored on a separate device for safety and security","cn":"（计算机）档案","lab":"computing","ex":{"en":"Optical media is perfect for storing archives of critical corporate data, such as financial records.","cn":"光学介质非常适合存储重要的公司数据档案，例如财务记录。"}},{"en":"to put or store a document or other material in an archive","cn":"把…存档；把…归档","pos":"verb"},{"en":"to move information that is not often needed to a different disk, tape or other computer to store it","cn":"将（不常用信息）存档","lab":"computing","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"档案;史料;记录;档案馆","en":"The archive or archives are a collection of documents and records that contain historical information. You can also use archives to refer to the place where archives are stored.","ex":{"en":"...the archives of the Imperial War Museum","cn":"帝国战争博物馆里的档案"}},{"pos":"ADJ 形容词","cn":"档案中的；档案的","en":"Archive material is information that comes from archives.","ex":{"en":"...archive material.","cn":"档案资料"}}]},"media":{"uk":"media/uk/archive__gb_1.mp3","us":"media/us/archive__us_1.mp3"},"examples":[{"en":"The BBC's archives are bulging with material.","cn":"英国广播公司的档案库材料极其丰富。"},{"en":"the National Sound Archive","cn":"国家音响档案馆"}]},"arch":{"oxford":{"phon":"ɑːtʃ","pos":"noun","senses":[{"en":"a curved structure that supports the weight of something above it, such as a bridge or the upper part of a building","cn":"拱（支撑如桥梁或房屋上部的弧形结构）","ex":{"en":"a bridge with three arches","cn":"有三个拱的桥。"}},{"en":"a structure with a curved top that is supported by straight sides, sometimes forming an entrance or built as a monument","cn":"拱门","ex":{"en":"Go through the arch and follow the path.","cn":"穿过拱门沿小径往前走。"}},{"en":"the raised part of the foot formed by a curved section of bones","cn":"足背；足弓"},{"en":"anything that forms a curved shape at the top","cn":"拱形；拱形物","ex":{"en":"the delicate arch of her eyebrows","cn":"她那弯弯的柳眉"}},{"en":"main; most important or most extreme","cn":"主要的；最重要的；极端的","ex":{"en":"archbishop","cn":"大主教"},"pos":"combining form"},{"en":"if you arch part of your body, or if it arches, it moves and forms a curved shape","cn":"（使）成弓形","g":"[transitive, intransitive]","ex":{"en":"The cat arched its back and hissed.","cn":"猫弓起背发出嘶嘶声。"},"pos":"verb"},{"en":"to be in a curved line or shape across or over something","cn":"呈拱形覆盖；呈弧形横跨","g":"[intransitive]","ex":{"en":"Tall trees arched over the path.","cn":"大树呈拱形遮阴了小道。"},"pos":"verb"},{"en":"seeming pleased with yourself because you know more about a situation than other people","cn":"调皮的；狡黠的","ex":{"en":"an arch tone of voice","cn":"调皮的语气"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拱;拱门;拱形结构","en":"An arch is a structure that is curved at the top and is supported on either side by a pillar, post, or wall."},{"pos":"N-COUNT 可数名词","cn":"弧形;弧形运动","en":"An arch is a curved line or movement."},{"pos":"N-COUNT 可数名词","cn":"足弓;足背","en":"The arch of your foot is the curved section at the bottom in the middle."},{"pos":"V-ERG 及物/不及物动词","cn":"弓着,佝着（背）等","en":"If you arch a part of your body such as your back or if it arches, you bend it so that it forms a curve.","ex":{"en":"Don't arch your back, keep your spine straight.","cn":"别佝着背，把腰挺直。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（表示惊奇或不赞同）扬起（眉毛）","en":"If you arch your eyebrows or if they arch, you move them upwards as a way of showing surprise or disapproval.","ex":{"en":"'Oh really?' he said, arching an eyebrow.","cn":"“哦，真的吗？”他扬起一边的眉毛说。"}},{"pos":"VERB 动词","cn":"拱起；成弓形；呈弧形运动","en":"If something arches in a particular direction, it makes a curved line or movement.","ex":{"en":"I gazed up at the domed ceiling arching overhead.","cn":"我抬头凝望着上方弧形的穹顶。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"神秘的；淘气的；调皮的","en":"An arch look is mysterious and mischievous.","ex":{"en":"Both of them looked at him with that curious, slightly amused and even arch expression.","cn":"他们俩都看着他，带着一副好奇的、有点觉得好笑甚至是淘气的表情。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"傲慢自大的","en":"If you say that someone is arch, you are criticizing them for talking or behaving as if they are better or more important than other people.","ex":{"en":"Their attempts to be casual have so far just looked arch or patronising.","cn":"他们本想做出漫不经心的样子，结果反而显得傲慢自大或自视甚高。"}}]},"media":{"img":["media/ldoce/img/arch.jpg","media/pic/architecture_comp.jpg"],"uk":"media/uk/arch__gb_1.mp3","us":"media/us/arch__us_1.mp3"},"examples":[{"en":"Marble Arch is a famous London landmark.","cn":"大理石拱门是伦敦著名的地标。"},{"en":"‘Guess what?’ she said archly. “","cn":"猜猜看？”她调皮地说道。"}]},"aristocrat":{"media":{"uk":"media/uk/aristocrat__gb_1.mp3","us":"media/us/aristocrat__us_1.mp3"},"oxford":{"phon":"ˈærɪstəkræt","pos":"noun","senses":[{"en":"a member of the aristocracy","cn":"（一个）贵族","ex":{"en":"The castle has been owned by a succession of wealthy aristocrats.","cn":"城堡的主人是历代富有的贵族"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"贵族（成员）","en":"An aristocrat is someone whose family has a high social rank, especially someone who has a title."}]}},"arrival":{"media":{"uk":"media/uk/arrival__gb_1.mp3","us":"media/us/arrival__us_1.mp3"},"oxford":{"phon":"əˈraɪvl","pos":"noun","senses":[{"en":"an act of coming or being brought to a place","cn":"到达；抵达","g":"[uncountable, countable]","ex":{"en":"We apologize for the late arrival of the train.","cn":"我们为火车误点表示歉意。"}},{"en":"the part of an airport that you go through when you arrive on a plane","cn":"（机场的）到达大厅","g":"[uncountable]","ex":{"en":"I made my way through arrivals.","cn":"我穿过机场到达大厅。"}},{"en":"a person or thing that comes to a place","cn":"到达者；抵达物","g":"[countable]","ex":{"en":"The first arrivals at the concert got the best seats.","cn":"最早来到音乐会的人坐上了最好的座位。"}},{"en":"the time when a new technology or idea is introduced","cn":"（新技术、新思想的）引进，采用，推行","g":"[uncountable]","ex":{"en":"the arrival of pay TV","cn":"收费电视的引进"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(人或交通工具的）到达，到来","en":"When a person or vehicle arrives at a place, you can refer to their arrival .","ex":{"en":"...the day after his arrival in England","cn":"他到英格兰的第二天"}},{"pos":"N-VAR 可变名词","cn":"上任；就任","en":"When someone starts a new job, you can refer to their arrival in that job.","ex":{"en":"...the power vacuum created by the arrival of a new president","cn":"新主席接任造成的权力真空"}},{"pos":"N-SING 单数名词","cn":"送到；运到；到货；出现","en":"When something is brought to you or becomes available, you can refer to its arrival .","ex":{"en":"I was flicking idly through a newspaper while awaiting the arrival of orange juice and coffee","cn":"我一边无所事事地翻着报纸，一边等着我点的橙汁和咖啡。"}},{"pos":"N-SING 单数名词","cn":"（某一时间的）到来；（某一事件的）发生","en":"When a particular time comes or a particular event happens, you can refer to its arrival.","ex":{"en":"He celebrated the arrival of the New Year with a party for his friends.","cn":"他为朋友们举行了一个聚会，庆祝新年的到来。"}},{"pos":"N-COUNT 可数名词","cn":"初到者；新来的人","en":"You can refer to someone who has just arrived at a place as a new arrival .","ex":{"en":"A high proportion of the new arrivals are skilled professionals","cn":"新来的人中很大一部分是技术熟练的专业人士。"}},{"pos":"N-SING 单数名词","cn":"（婴儿的）出生，诞生","en":"When a baby is born, you can refer to its arrival.","ex":{"en":"...a couple anticipating the arrival of a new child.","cn":"盼望着孩子出生的一对夫妇"}},{"pos":"N-COUNT 可数名词","cn":"新生儿","en":"You can refer to a baby who has just been born as a new arrival .","ex":{"en":"Her father was besotted with the new arrival.","cn":"她的父亲完全沉浸在新生儿带来的喜悦中。"}}]},"examples":[{"en":"The first arrivals at the concert got the best seats.","cn":"最早来到音乐会的人坐上了最好的座位。"},{"en":"There are 120 arrivals and departures every day.","cn":"每天有 120 次航班离港和抵港。"}]},"aristocratic":{"media":{"uk":"media/uk/aristocratic__gb_1.mp3","us":"media/us/aristocratic__us_1.mp3"},"oxford":{"phon":"ˌærɪstəˈkrætɪk","pos":"adjective","senses":[{"en":"belonging to or typical of the aristocracy","cn":"贵族的","ex":{"en":"an aristocratic name/family/lifestyle","cn":"贵族姓氏／家庭／生活方式"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"贵族的；贵族式的","en":"Aristocratic means belonging to or typical of the aristocracy.","ex":{"en":"...a wealthy, aristocratic family","cn":"富有的贵族家庭"}}]},"examples":[{"en":"an aristocratic name/family/lifestyle","cn":"贵族姓氏/家庭/生活方式"},{"en":"an aristocratic family","cn":"贵族家庭"}]},"archaeologist":{"media":{"uk":"media/uk/archaeologist__gb_1.mp3","us":"media/us/archaeologist__us_1.mp3"},"oxford":{"phon":"ˌɑːkiˈɒlədʒɪst","pos":"noun","senses":[{"en":"a person who studies archaeology","cn":"考古学家","ex":{"en":"examples of life thousands of years ago, unearthed by archaeologists","cn":"考古学家发掘出土的几千年前的生物化石"}}]}},"arrive":{"media":{"uk":"media/uk/arrive__gb_1.mp3","us":"media/us/arrive__us_1.mp3"},"oxford":{"phon":"əˈraɪv","pos":"verb","senses":[{"en":"to get to a place, especially at the end of a journey","cn":"到达；抵达","g":"[intransitive]","ex":{"en":"I'll wait until they arrive.","cn":"我会一直等到他们来。"}},{"en":"to be brought to somebody","cn":"送达；寄到","g":"[intransitive]","ex":{"en":"A letter arrived for you this morning.","cn":"今天上午来了一封给你的信。"}},{"en":"to happen or to come, especially when you have been waiting for it","cn":"发生；到来","g":"[intransitive]","ex":{"en":"The wedding day finally arrived.","cn":"婚礼这一天终于到来。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（人或交通工具）到达，抵达","en":"When a person or vehicle arrives at a place, they come to it at the end of a journey.","ex":{"en":"Fresh groups of guests arrived","cn":"新的客人接踵而来。"}},{"pos":"VERB 动词","cn":"初次来到；初来乍到","en":"When you arrive at a place, you come to it for the first time in order to stay, live, or work there.","ex":{"en":"...in the old days before the European settlers arrived in the country.","cn":"在欧洲殖民者来到这个国家之前的旧日时光"}},{"pos":"VERB 动词","cn":"被送达；被带来","en":"When something such as letter or meal arrives, it is brought or delivered to you.","ex":{"en":"Any entry arriving after the closing date will not be considered","cn":"截止日期之后报名参赛的人将不予考虑。"}},{"pos":"VERB 动词","cn":"（新产品或发明）出现，到来，问世","en":"When something such as a new product or invention arrives, it becomes available.","ex":{"en":"Several long-awaited videos will finally arrive in the shops this month","cn":"几部让人翘首企盼的录像片终于将在这个月到货。"}},{"pos":"VERB 动词","cn":"（尤指经过等待或期盼后）来临，到来","en":"When a particular moment or event arrives, it happens, especially after you have been waiting for it or expecting it.","ex":{"en":"The time has arrived when I need to give up smoking.","cn":"我戒烟的时机已到。"}},{"pos":"VERB 动词","cn":"作出（决定）","en":"When you arrive at something such as a decision, you decide something after thinking about it or discussing it.","ex":{"en":"...if the jury cannot arrive at a unanimous decision","cn":"如果陪审团不能作出一致判决"}},{"pos":"VERB 动词","cn":"（婴儿）出生，降生","en":"When a baby arrives, it is born.","ex":{"en":"It's very unlikely that your baby will arrive before you get to hospital.","cn":"你的孩子不大可能在你到达医院之前就出生。"}},{"pos":"VERB 动词","cn":"取得成功；成名","en":"If you say that someone has arrived, you mean that they have become successful or famous.","ex":{"en":"These are cars which show you've arrived and had a good time along the way.","cn":"这样的车可以显示你已功成名就，并且一路顺风顺水。"}}]},"examples":[{"en":"He knew he had arrived when he was shortlisted for the Booker prize.","cn":"被列入布克小说作品奖决选名单后，他知道自己成功了。"},{"en":"Send your application to arrive by 31 October.","cn":"申请信要在 10 月 31 日前寄到。"}]},"article":{"media":{"uk":"media/uk/article__gb_1.mp3","us":"media/us/article__us_1.mp3"},"oxford":{"phon":"ˈɑːtɪkl","pos":"noun","senses":[{"en":"a piece of writing about a particular subject in a newspaper or magazine, on a website, etc.","cn":"（报刊或网络上的）文章，论文，报道","ex":{"en":"to read/write/publish an article","cn":"读／写／发表一篇文章"}},{"en":"a separate item in an agreement or a contract","cn":"（协议、契约的）条款，项","lab":"law","ex":{"en":"Article 10 of the European Convention guarantees free speech.","cn":"《欧洲公约》第 10 条保障言论自由。"}},{"en":"a particular item or separate thing, especially one of a set","cn":"物件，物品（尤指整套中的一件）","lab":"formal","ex":{"en":"articles of clothing","cn":"衣物"}},{"en":"the words a and an (the indefinite article) or the (the definite article)","cn":"冠词（a 和 an 为不定冠词，the 为定冠词）","lab":"grammar","ex":{"en":"Names of countries in English do not usually take an article.","cn":"在英语中，国名通常不带冠词。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（报纸、杂志的）文章","en":"An article is a piece of writing that is published in a newspaper or magazine.","ex":{"en":"...a newspaper article","cn":"一篇报载文章"}},{"pos":"N-COUNT 可数名词","cn":"物品；物件","en":"You can refer to objects as articles of some kind.","ex":{"en":"...articles of clothing","cn":"衣物"}},{"pos":"PHRASE 短语","cn":"正品;真货","en":"If you describe something as the genuine article, you are emphasizing that it is genuine, and often that it is very good.","ex":{"en":"The vodka was the genuine article.","cn":"这种伏特加酒是正品。"}},{"pos":"N-COUNT 可数名词","cn":"（契约、文件的）条款，条文，项目","en":"An article of a formal agreement or document is a section of it which deals with a particular point.","ex":{"en":"The country appears to be violating several articles of the convention.","cn":"这个国家看起来违反了公约中的好几项条款。"}},{"pos":"N-PLURAL 复数名词","cn":"见习契约","en":"Someone who is in articles is being trained as a lawyer or accountant by a firm with whom they have a written agreement.","ex":{"en":"In 1986, 44 per cent of those admitted to articles were women.","cn":"1986年，44％的实习生为女性。"}},{"pos":"N-COUNT 可数名词","cn":"冠词（a和an是不定冠词，the是定冠词）","en":"In grammar, an article is a kind of determiner. In English, 'a' and 'an' are called the indefinite article, and 'the' is called the definite article ."}]},"examples":[{"en":"Have you seen that article about young fashion designers?","cn":"你见到了关于年轻时装设计师的那篇文章没有？"},{"en":"The articles found in the car helped the police to identify the body.","cn":"在汽车上发现的物品有助于警方辨认死者身分。"}]},"arrange":{"oxford":{"phon":"əˈreɪndʒ","pos":"verb","senses":[{"en":"to plan or organize something in advance","cn":"安排；筹备","g":"[transitive, intransitive]","ex":{"en":"The party was arranged quickly.","cn":"聚会很快就安排好了。"}},{"en":"to put something in a particular order; to make something neat or attractive","cn":"整理；排列；布置","g":"[transitive]","ex":{"en":"The books are arranged alphabetically by author.","cn":"这些书是按作者姓名字母顺序排列的。"}},{"en":"to change a piece of music so that it is suitable for a particular instrument or voice","cn":"改编（乐曲）","g":"[transitive]","ex":{"en":"He arranged traditional folk songs for the piano.","cn":"他把传统民歌改编成钢琴曲。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"安排；准备；筹划","en":"If you arrange an event or meeting, you make plans for it to happen.","ex":{"en":"She arranged an appointment for Friday afternoon at four-fifteen","cn":"她在星期五下午4点15分安排了一次会面。"}},{"pos":"VERB 动词","cn":"商定；谈妥","en":"If you arrange with someone to do something, you make plans with them to do it.","ex":{"en":"I've arranged to see him on Friday morning","cn":"我已安排好星期五上午见他。"}},{"pos":"VERB 动词","cn":"安排；准备","en":"If you arrange something for someone, you make it possible for them to have it or to do it.","ex":{"en":"I will arrange for someone to take you round","cn":"我会安排人带你转转。"}},{"pos":"VERB 动词","cn":"排列；布置；整理","en":"If you arrange things somewhere, you place them in a particular position, usually in order to make them look attractive or tidy.","ex":{"en":"When she has a little spare time she enjoys arranging dried flowers","cn":"她稍有空闲便喜欢摆弄干花。"}},{"pos":"VERB 动词","cn":"改编（乐曲）","en":"If a piece of music is arranged by someone, it is changed or adapted so that it is suitable for particular instruments or voices, or for a particular performance.","ex":{"en":"The songs were arranged by another well-known bass player, Ron Carter.","cn":"另一位著名的低音提琴演奏家罗恩·卡特改编了这些歌曲。"}}]},"media":{"uk":"media/uk/arrange__gb_1.mp3","us":"media/us/arrange__us_1.mp3"},"examples":[{"en":"I've arranged with the neighbours about feeding the cat while we are away.","cn":"我们外出期间给猫喂食的事，我已和邻居安排妥了。"},{"en":"I've arranged that we can borrow their car.","cn":"我已经说好了，我们可以借用他们的车。"}]},"arms":{"media":{"uk":"media/uk/arms__gb_1.mp3","us":"media/us/arms__us_1.mp3"},"oxford":{"phon":"ɑːmz","pos":"noun","senses":[{"en":"weapons, especially as used by the army, navy, etc.","cn":"兵器；武器","lab":"formal","ex":{"en":"arms and ammunition","cn":"兵器和弹药"}},{"en":"a design or a shield that is a special symbol of a family, city or other organization","cn":"盾形纹章；盾徽","ex":{"en":"the King’s Arms (= used as the name of a pub)","cn":"国王盾形徽章（酒吧名）"}}]},"examples":[{"en":"Police officers in the UK do not usually carry arms.","cn":"英国警察通常不携带武器。"},{"en":"the King's Arms (= used as the name of a pub)","cn":"国王盾形徽章（酒吧名）"}]},"aristocracy":{"media":{"uk":"media/uk/aristocracy__gb_1.mp3","us":"media/us/aristocracy__us_1.mp3"},"oxford":{"phon":"ˌærɪˈstɒkrəsi","pos":"noun","senses":[{"en":"(in some countries) people born in the highest social class, who have special titles","cn":"（某些国家的）贵族","ex":{"en":"members of the aristocracy","cn":"贵族成员"}}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"贵族（阶层）","en":"The aristocracy is a class of people in some countries who have a high social rank and special titles.","ex":{"en":"...a member of the aristocracy.","cn":"一个贵族成员"}}]},"examples":[{"en":"members of the aristocracy","cn":"贵族成员"},{"en":"dukes, earls, and other members of the aristocracy","cn":"公爵﹑伯爵及其他贵族成员"}]},"arm":{"media":{"uk":"media/uk/arm__gb_1.mp3","us":"media/us/arm__us_1.mp3","img":["media/ldoce/img/antique_chair.jpg"]},"oxford":{"phon":"ɑːm","pos":"noun","senses":[{"en":"either of the two long parts that stick out from the top of the body and connect the shoulders to the hands","cn":"臂；手臂；上肢","lab":"informal","sc":"part of body","ex":{"en":"He escaped with only a broken arm.","cn":"他得以逃生，只是断了一条胳膊。"}},{"en":"the part of a piece of clothing that covers the arm","cn":"袖子","sc":"of clothing","ex":{"en":"The arms will need shortening.","cn":"手臂需要缩短。"}},{"en":"the part of a chair, etc. on which you rest your arms","cn":"扶手","sc":"of chair","ex":{"en":"She perched on the arm of his chair.","cn":"她坐在他的椅子扶手上。"}},{"en":"a long narrow part of an object or a machine, especially one that moves","cn":"臂状物（尤指可移动的物体部分或机器部件）","sc":"of a machine","ex":{"en":"a robotic arm","cn":"机械臂"}},{"en":"a long narrow piece of water or land that is joined to a larger area","cn":"狭长港湾；（连接较大地区的）狭长地带","sc":"of water/land","ex":{"en":"A small bridge spans the arm of the river.","cn":"一座小桥横跨河湾。"}},{"en":"a section of a large organization that deals with one particular activity","cn":"分部；职能部门","g":"[usually singular]","sc":"of organization","ex":{"en":"the research arm of the company","cn":"公司的研究部门"}},{"en":"to provide weapons for yourself/somebody in order to fight a battle or a war","cn":"武装；装备；备战","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"The country was arming against the enemy.","cn":"这个国家正在备战迎击敌人。"},"pos":"verb"},{"en":"to make a bomb, etc. ready to explode","cn":"使（炸弹等）随时爆炸","g":"[transitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手臂;上肢","en":"Your arms are the two long parts of your body that are attached to your shoulders and that have your hands at the end.","ex":{"en":"She stretched her arms out","cn":"她张开双臂。"}},{"pos":"N-COUNT 可数名词","cn":"衣袖;袖子","en":"The arm of a piece of clothing is the part of it that covers your arm."},{"pos":"N-COUNT 可数名词","cn":"（椅子的）靠手，扶手","en":"The arm of a chair is the part on which you rest your arm when you are sitting down."},{"pos":"N-COUNT 可数名词","cn":"（物体的）臂，杆","en":"An arm of an object is a long thin part of it that sticks out from the main part.","ex":{"en":"...the lever arm of the machine.","cn":"机器的操纵杆"}},{"pos":"N-COUNT 可数名词","cn":"（陆地的）狭长地带;狭长港湾","en":"An arm of land or water is a long thin area of it that is joined to a broader area.","ex":{"en":"At the end of the other arm of Cardigan Bay is Bardsey Island.","cn":"在卡迪根湾的另一狭长地段的尾端是巴德西岛。"}},{"pos":"N-COUNT 可数名词","cn":"分支机构；部门","en":"An arm of an organization is a section of it that operates in a particular country or that deals with a particular activity.","ex":{"en":"Millicom Holdings is the British arm of an American company.","cn":"米雷康姆控股有限公司是一家美国公司在英国的分支机构。"}},{"pos":"PHRASE 短语","cn":"臂挽臂地","en":"If two people are walking arm in arm, they are walking together with their arms linked.","ex":{"en":"He walked from the court arm in arm with his wife.","cn":"他和妻子挽着胳膊走出法庭。"}},{"pos":"PHRASE 短语","cn":"（价格）昂贵","en":"If you say that something costs an arm and a leg, you mean that it is very expensive.","ex":{"en":"A week at a health farm can cost an arm and a leg.","cn":"在健身中心呆一个星期的花费会很昂贵。"}},{"pos":"PHRASE 短语","cn":"一臂之远；在伸手可及处","en":"If you hold something at arm's length, you hold it away from your body with your arm straight.","ex":{"en":"He struck a match, and held it at arm's length.","cn":"他划亮一根火柴，伸长胳膊举着。"}},{"pos":"PHRASE 短语","cn":"与…保持距离","en":"If you keep someone at arm's length, you avoid becoming too friendly or involved with them.","ex":{"en":"She had always kept his family at arm's length.","cn":"她一直与他的家人保持一定距离。"}},{"pos":"PHRASE 短语","cn":"（清单）很长","en":"If you say that a list is as long as your arm, you are emphasizing that it is very long."},{"pos":"PHRASE 短语","cn":"热烈地;友好地","en":"If you welcome some action or change with open arms, you are very pleased about it. If you welcome a person with open arms, you are very pleased about their arrival.","ex":{"en":"They would no doubt welcome the action with open arms","cn":"他们无疑将热烈欢迎这一举动。"}},{"pos":"PHRASE 短语","cn":"说服","en":"If you twist someone's arm, you persuade them to do something.","ex":{"en":"She had twisted his arm to get him to invite her.","cn":"她说服他向自己发出邀请。"}},{"pos":"N-PLURAL 复数名词","cn":"武器，军火，军备（尤指炸弹和枪支）","en":"Arms are weapons, especially bombs and guns.","ex":{"en":"The IRA had extensive supplies of arms.","cn":"爱尔兰共和军有庞大的军备。"}},{"pos":"VERB 动词","cn":"武装；装备","en":"If you arm someone with a weapon, you provide them with a weapon.","ex":{"en":"She'd been so terrified that she had armed herself with a loaded rifle","cn":"她吓坏了，于是拿了一支上了膛的步枪。"}},{"pos":"VERB 动词","cn":"（给…）提供，配备;支持","en":"If you arm someone with something that will be useful in a particular situation, you provide them with it.","ex":{"en":"She thought that if she armed herself with all the knowledge she could gather she could handle anything","cn":"她以为，如果获取了所有能学到的知识，就能处理任何事。"}},{"pos":"N-PLURAL 复数名词","cn":"（城市或贵族家庭的）盾徽，（盾形）徽章，纹章（常用于英国酒馆名中）","en":"The arms of a city or of a noble family are its coat of arms. Arms is often used in the names of British pubs.","ex":{"en":"...china painted with the arms of Philippe V.","cn":"画有腓力五世的盾徽的瓷器"}},{"pos":"PHRASE 短语","cn":"（以自卫为目的）持有武器","en":"A person's right to bear arms is their right to own and use guns, as a means of defence."},{"pos":"PHRASE 短语","cn":"放下武器;投降","en":"If soldiers lay down their arms, they stop fighting and give up their weapons."},{"pos":"PHRASE 短语","cn":"拿起武器;准备与…战斗","en":"If one group or countrytakes up arms against another, they prepare to attack and fight them.","ex":{"en":"They threatened to take up arms against the government if their demands were not met.","cn":"他们威胁，如果要求得不到满足就要以武力抵抗政府。"}},{"pos":"PHRASE 短语","cn":"武装起来的;处于战备状态","en":"If a country has people under arms, it has people trained to use weapons and to fight a war.","ex":{"en":"There are nearly four million soldiers under arms in this country.","cn":"该国有将近400万现役士兵。"}},{"pos":"PHRASE 短语","cn":"非常愤怒;极力反对;强烈抗议","en":"If people are up in arms about something, they are very angry about it and are protesting strongly against it.","ex":{"en":"Environmental groups are up in arms about plans to sink an oil well close to Hadrian's Wall.","cn":"环保组织极力反对在哈德良长城附近打油井。"}}]},"examples":[{"en":"( figurative ) She had armed herself for the meeting with all the latest statistics.","cn":"为了这次会议，她准备了所有最新统计资料。"},{"en":"He walked in with a tall blonde on his arm (= next to him and holding his arm).","cn":"他手挽着一个高个子金发女郎走了进来。"}]},"ardent":{"media":{"uk":"media/uk/ardent__gb_1.mp3","us":"media/us/ardent__us_1.mp3"},"oxford":{"phon":"ˈɑːdnt","pos":"adjective","senses":[{"en":"very enthusiastic and showing strong feelings about something/somebody","cn":"热烈的；激情的","ex":{"en":"an ardent supporter of European unity","cn":"欧洲一体化的热烈支持者"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热情的;热烈的;激动的","en":"Ardent is used to describe someone who has extremely strong feelings about something or someone.","ex":{"en":"He's been one of the most ardent supporters of the administration's policy.","cn":"他一向是政府政策最热情的支持者之一。"}}]},"examples":[{"en":"an ardent supporter of European unity","cn":"欧洲统一的热烈支持者"},{"en":"an ardent supporter of free trade","cn":"自由贸易的热心支持者"}]},"armed":{"media":{"uk":"media/uk/armed__gb_1.mp3","us":"media/us/armed__us_1.mp3"},"oxford":{"phon":"ɑːmd","pos":"adjective","senses":[{"en":"involving the use of weapons","cn":"使用武器的；用武力的","ex":{"en":"an armed robbery","cn":"持械抢劫"}},{"en":"carrying a weapon, especially a gun","cn":"携带武器的；持枪的；荷枪实弹的","ex":{"en":"The man is armed and dangerous.","cn":"这个男子有枪，是个危险分子。"}},{"en":"knowing something or carrying something that you need in order to help you to perform a task","cn":"备有所需的","ex":{"en":"He was armed with all the facts.","cn":"他备有所需的全部事实材料。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"携带武器（通常为枪支）的","en":"Someone who is armed is carrying a weapon, usually a gun.","ex":{"en":"City police said the man was armed with a revolver.","cn":"市警方称那名男子携带了一支左轮手枪。"}},{"pos":"ADJ 形容词","cn":"使用武器的","en":"An armed attack or conflict involves people fighting with guns or carrying weapons.","ex":{"en":"I call on everyone to renounce the use of violence and armed struggle","cn":"我呼吁每个人都放弃使用暴力和武装斗争。"}}]},"examples":[{"en":"The man is armed and dangerous.","cn":"这个男子有枪，是个危险分子。"},{"en":"He was armed with all the facts.","cn":"他备有所需的全部事实材料。"}]},"arcs":{"oxford":{"phon":"ɑːk","pos":"noun","senses":[{"en":"( geometry","cn":"几何 ) part of a circle or a curved line 弧"},{"en":"a curved shape","cn":"弧形"}]}},"arabian":{"oxford":{"phon":"əˈreɪbiən","pos":"adjective","senses":[{"en":"of or connected with Arabia","cn":"阿拉伯的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"阿拉伯的；（尤指）沙特阿拉伯的","en":"Arabian means belonging or relating to Arabia, especially to Saudi Arabia.","ex":{"en":"...the Arabian Peninsula.","cn":"阿拉伯半岛"}}]},"media":{"uk":"media/uk/arabian__gb_1.mp3","us":"media/us/arabian__us_1.mp3"},"examples":[{"en":"the Arabian peninsula","cn":"阿拉伯半岛"},{"en":"Arab children","cn":"阿拉伯儿童"}]},"archway":{"media":{"uk":"media/uk/archway__gb_1.mp3","us":"media/us/archway__us_1.mp3"},"oxford":{"phon":"ˈɑːtʃweɪ","pos":"noun","senses":[{"en":"a passage or an entrance with an arch over it","cn":"拱道；拱门","ex":{"en":"We went through a stone archway into the courtyard.","cn":"我们穿过石拱门进入院子。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拱廊;拱道;拱门","en":"An archway is a passage or entrance that has a curved roof.","ex":{"en":"Access was via a narrow archway.","cn":"通道入口是一道狭窄的拱门。"}}]},"examples":[{"en":"We went through a stone archway into the courtyard.","cn":"我们穿过石拱门进入院子。"},{"en":"He was standing in the archway outside the club.","cn":"他站在俱乐部外的拱廊里。"}]},"ark":{"media":{"uk":"media/uk/ark__gb_1.mp3","us":"media/us/ark__us_1.mp3"},"oxford":{"phon":"ɑːk","pos":"noun","senses":[{"en":"a large boat which Noah built to save his family and two of every type of animal from the flood","cn":"方舟，诺亚方舟（诺亚为家人及一对对各种动物避洪水所造的大船）"},{"en":"( BrE ) ( informal ) if sb says that an object or a custom is out of the ark or went out with the ark , they think that it is very old-fashioned","cn":"极古老；十分陈旧；过时"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"方舟（《圣经》中，大洪水时挪亚为救家人和动物而建造的大船）","en":"In the Bible, the ark was a large boat which Noah built in order to save his family and two of every kind of animal from the Flood."}]},"examples":[{"en":"Some of the school's computer equipment is out of the Ark.","cn":""}]},"array":{"media":{"uk":"media/uk/array__gb_1.mp3","us":"media/us/array__us_1.mp3"},"oxford":{"phon":"əˈreɪ","pos":"noun","senses":[{"en":"a group or collection of things or people, often one that is large or impressive","cn":"大堆；大群；大量","g":"[usually singular]","ex":{"en":"a vast array of bottles of different shapes and sizes","cn":"一大批形状大小不一的瓶子"}},{"en":"a way of organizing and storing related data in a computer memory","cn":"数组；阵列","lab":"computing"},{"en":"a set of numbers, signs or values arranged in rows and columns","cn":"数组；阵列","lab":"specialist"},{"en":"to arrange a group of things in an attractive way or so that they are in order","cn":"布置；排列","ex":{"en":"Jars of all shapes and sizes were arrayed on the shelves.","cn":"在搁架上整齐地排列着大大小小各式各样的罐子。"},"pos":"verb"},{"en":"to arrange soldiers in a position from which they are ready to attack","cn":"配置（兵力）","lab":"specialist","ex":{"en":"the hostile forces arrayed against them","cn":"为对付他们而部署的敌军"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"一大批；一大群","en":"An array of different things or people is a large number or wide range of them.","ex":{"en":"As the deadline approached she experienced a bewildering array of emotions","cn":"随着最后期限的临近，她开始心绪纷乱，不知所措。"}},{"pos":"N-COUNT 可数名词","cn":"陈列;布置","en":"An array of objects is a collection of them that is displayed or arranged in a particular way.","ex":{"en":"There was an impressive array of pill bottles stacked on top of the fridge","cn":"冰箱上显眼地摆放着许多药瓶。"}},{"pos":"N-COUNT 可数名词","cn":"（多个望远镜、太阳能电池板之类的仪器设备连接在一起构成的）阵列","en":"An array of instruments such as telescopes or solar panels is a number of them that are connected together to form a single unit."},{"pos":"N-COUNT 可数名词","cn":"数列;数组;阵列","en":"In science and mathematics, an array of things such as atoms or numbers is a regular pattern or structure that is formed by them.","ex":{"en":"...methods which can be used to create an ordered array of molecules within materials","cn":"能使材料内部的分子有序排列的方法"}}]},"examples":[{"en":"Jars of all shapes and sizes were arrayed on the shelves.","cn":"在搁架上整齐地排列着大大小小各式各样的罐子。"},{"en":"a vast array of bottles of different shapes and sizes","cn":"一大批形状大小不一的瓶子"}]},"arid":{"media":{"uk":"media/uk/arid__gb_1.mp3","us":"media/us/arid__us_1.mp3"},"oxford":{"phon":"ˈærɪd","pos":"adjective","senses":[{"en":"having little or no rain; very dry","cn":"干旱的；干燥的","ex":{"en":"arid and semi-arid deserts","cn":"干旱和半干旱的沙漠"}},{"en":"with nothing new or interesting in it","cn":"枯燥的；乏味的；毫无新意的","lab":"formal","ex":{"en":"an arid discussion","cn":"枯燥的讨论"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"干旱的;不毛的","en":"Arid land is so dry that very few plants can grow on it.","ex":{"en":"...new strains of crops that can withstand arid conditions.","cn":"能抵抗干旱条件的新品种作物"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"枯燥无味的；乏善可陈的","en":"If you describe something such as a period of your life or an academic subject as arid, you mean that it has so little interest, excitement, or purpose that it makes you feel bored or unhappy.","ex":{"en":"She had given him the only joy his arid life had ever known.","cn":"她为他枯燥无味的生活带来了从未有过的乐趣。"}}]},"examples":[{"en":"arid and semi-arid deserts","cn":"干旱和半干旱的沙漠"},{"en":"an arid discussion","cn":"枯燥的讨论"}]},"armour":{"oxford":{"phon":"ˈɑːmə(r)","pos":"noun","senses":[{"en":"special metal clothing that soldiers wore in the past to protect their bodies while fighting; special clothing that soldiers or police officers wear to protect their bodies","cn":"盔甲；甲冑；防弹衣","lab":"figurative","ex":{"en":"a suit of armour","cn":"一副盔甲"}},{"en":"metal covers that protect ships and military vehicles such as tanks","cn":"（军舰、坦克等的）装甲，防弹钢板"},{"en":"military vehicles used in war","cn":"装甲部队；装甲车辆","lab":"specialist","ex":{"en":"an attack by infantry and armour","cn":"步兵和装甲兵的进攻"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（旧时的）盔甲，铠甲","en":"In former times, armour was special metal clothing that soldiers wore for protection in battle.","ex":{"en":"...the collection of weapons and armour in the historic White Tower.","cn":"历史古迹白塔中所收藏的武器和盔甲"}},{"pos":"N-UNCOUNT 不可数名词","cn":"装甲部队（作战中使用的坦克等军用车辆的总称）","en":"Armour consists of tanks and other military vehicles used in battle.","ex":{"en":"...the biggest movement of heavy British armour since the Second World War.","cn":"二战以来规模最大的英国重型装甲部队调动"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（车辆的）装甲，铁甲，装甲钢板","en":"Armour is a hard, usually metal, covering that protects a vehicle against attack.","ex":{"en":"...a formidable warhead that can penetrate the armour of most tanks.","cn":"能穿透大多数坦克装甲的威力巨大的弹头"}},{"pos":"See also:","cn":"","en":"a chink in someone's armour→see: ; knight in shining armour→see: ;"}]},"media":{"uk":"media/uk/armour__gb_1.mp3","us":"media/us/armour__us_1.mp3"},"examples":[{"en":"( figurative ) Monkeys do not have any kind of protective armour and use their brains to solve problems.","cn":"猴子没有任何防身的盔甲，就动脑筋解决问题。"},{"en":"an attack by infantry and armour","cn":"步兵和装甲兵的进攻"}]},"arena":{"oxford":{"phon":"əˈriːnə","pos":"noun","senses":[{"en":"a place with a flat open area in the middle and seats around it where people can watch sports and entertainment","cn":"圆形运动场；圆形剧场","ex":{"en":"a concert at Wembley Arena","cn":"在温布利体育馆举行的音乐会"}},{"en":"an area of activity that interests the public, especially one where there is a lot of opposition between different groups or countries","cn":"斗争场所；竞争舞台；活动场所","lab":"formal","ex":{"en":"the political/international arena","cn":"政治／国际舞台"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"运动场；竞技场；体育场","en":"An arena is a place where sports, entertainments, and other public events take place. It has seats around it where people sit and watch.","ex":{"en":"...the largest indoor sports arena in the world.","cn":"世界上最大的室内体育场"}},{"pos":"N-COUNT 可数名词","cn":"活动领域;舞台","en":"You can refer to a field of activity, especially one where there is a lot of conflict or action, as an arena of a particular kind.","ex":{"en":"He made it clear he had no intention of withdrawing from the political arena","cn":"他清楚地表明他无意退出政治舞台。"}}]},"media":{"uk":"media/uk/arena__gb_1.mp3","us":"media/us/arena__us_1.mp3"},"examples":[{"en":"a concert at Wembley Arena","cn":"在文布利运动场举行的音乐会"},{"en":"the political/international arena","cn":"政治/国际舞台"}]},"armies":{"oxford":{"phon":"ˈɑːmi","pos":"noun","senses":[{"en":"a large organized group of soldiers who are trained to fight on land","cn":"陆上作战军队；陆军部队"},{"en":"the part of a country's armed forces that fights on land （","cn":"一国的）陆军"}]},"media":{"uk":"media/uk/army__gb_1.mp3","us":"media/us/army__us_1.mp3"}},"arrangement":{"oxford":{"phon":"əˈreɪndʒmənt","pos":"noun","senses":[{"en":"a plan or preparation that you make so that something can happen","cn":"安排；筹备","g":"[countable, usually plural]","ex":{"en":"Travel and accommodation arrangements have been finalized.","cn":"旅行和住宿安排已经确定。"}},{"en":"the way things are done or organized","cn":"安排方式；布置","g":"[countable, usually plural]","ex":{"en":"She's happy with her unusual living arrangements.","cn":"她对自己不同寻常的生活安排方式感到很得意。"}},{"en":"an agreement that you make with somebody that you can both accept","cn":"商定；约定","g":"[countable, uncountable]","ex":{"en":"We can come to an arrangement over the price.","cn":"我们可以就价格问题达成一项协议。"}},{"en":"a group of things that are organized or placed in a particular order or position; the act of placing things in a particular order","cn":"整理好的东西；整理；排列；布置","g":"[countable, uncountable]","ex":{"en":"plans of the possible seating arrangements","cn":"几种可行的座次安排方案"}},{"en":"a piece of music that has been changed, for example for another instrument to play","cn":"改编乐曲","g":"[countable]","ex":{"en":"an arrangement of a Mozart aria for clarinet and piano","cn":"为单簧管和钢琴改编的莫扎特咏叹调"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"安排；准备；筹划","en":"Arrangements are plans and preparations which you make so that something will happen or be possible.","ex":{"en":"The staff is working frantically on final arrangements for the summit","cn":"工作人员正紧张忙乱地为峰会做最后准备。"}},{"pos":"N-COUNT 可数名词","cn":"商定；约定；协议","en":"An arrangement is an agreement that you make with someone to do something.","ex":{"en":"The caves can be visited only by prior arrangement","cn":"这些洞穴只接受预约参观。"}},{"pos":"N-COUNT 可数名词","cn":"排列；布置；整理","en":"An arrangement of things, for example flowers or furniture, is a group of them displayed in a particular way.","ex":{"en":"The house was always decorated with imaginative flower arrangements.","cn":"这所房子总是摆放着富有创意的插花。"}},{"pos":"N-COUNT 可数名词","cn":"（乐曲的）改编","en":"If someone makes an arrangement of a piece of music, they change it so that it is suitable for particular voices or instruments, or for a particular performance.","ex":{"en":"...an arrangement of a well-known piece by Mozart","cn":"莫扎特一首名曲的改编曲"}}]},"media":{"uk":"media/uk/arrangement__gb_1.mp3","us":"media/us/arrangement__us_1.mp3"},"examples":[{"en":"She's happy with her unusual living arrangements.","cn":"她对自己不同寻常的生活安排方式感到很得意。"},{"en":"You can cash cheques here by prior arrangement with the bank.","cn":"你事先和银行商妥，就可以在这里兑现支票。"}]},"around":{"media":{"uk":"media/uk/around__gb_1.mp3","us":"media/us/around__us_1.mp3"},"oxford":{"phon":"əˈraʊnd","pos":"preposition","senses":[{"en":"surrounding somebody/something; on each side of something","cn":"围绕；环绕","ex":{"en":"The house is built around a central courtyard.","cn":"这房子是围绕着中央的庭院而建的。"}},{"en":"on, to or from the other side of somebody/something","cn":"在那边；到那边；从那边","ex":{"en":"Our house is just around the corner.","cn":"过了拐角就是我们的房子。"}},{"en":"in a circle","cn":"绕着","ex":{"en":"They walked around the lake.","cn":"他们绕着湖边行走。"}},{"en":"in or to many places in an area","cn":"到处；向各处","lab":"British English","ex":{"en":"They walked around the town looking for a place to eat.","cn":"他们在城里到处寻找吃饭的地方。"}},{"en":"to fit in with particular people, ideas, etc.","cn":"同…一致；适合；符合","ex":{"en":"I can't arrange everything around your timetable!","cn":"我不可能事事都按着你的时刻表安排！"}},{"en":"in connection with somebody/something","cn":"有关的；相关的","ex":{"en":"He has issues around food and dieting.","cn":"他有饮食失调的问题。"}},{"en":"approximately","cn":"大约","ex":{"en":"He arrived around five o'clock.","cn":"他大约是五点钟到的。"},"pos":"adverb"},{"en":"on every side; surrounding somebody/something","cn":"周围；四周","ex":{"en":"I could hear laughter all around.","cn":"我可以听见周围的笑声。"},"pos":"adverb"},{"en":"moving in a circle","cn":"围绕；环绕","lab":"especially North American English","ex":{"en":"How do you make the wheels go around?","cn":"你怎样使这些轮子转动起来？"},"pos":"adverb"},{"en":"in a circle or curve to face another way or the opposite way","cn":"转弯；掉转；掉头","lab":"especially North American English","ex":{"en":"She turned the car around and drove off.","cn":"她把轿车掉头开走了。"},"pos":"adverb"},{"en":"measured in a circle","cn":"以圆周计算","lab":"especially North American English","ex":{"en":"an old tree that was at least ten feet around","cn":"合抱至少十英尺的古树"},"pos":"adverb"},{"en":"in or to many places","cn":"到处；向各处","ex":{"en":"We were all running around trying to get ready in time.","cn":"我们东奔西跑，望能按时准备就绪。"},"pos":"adverb"},{"en":"used to describe activities that have no real purpose","cn":"闲散地；无目的地","ex":{"en":"There were several young people sitting around looking bored.","cn":"有几个年轻人闲坐着，一副无聊的样子。"},"pos":"adverb"},{"en":"present in a place; available","cn":"出现；现有；可用","ex":{"en":"She must be somewhere around here.","cn":"她肯定在这附近。"},"pos":"adverb"},{"en":"active and well known in a sport, profession, etc.","cn":"（体育运动、专业等中）走红的，活跃的","ex":{"en":"a new tennis champion who could be around for a long time","cn":"可能会走红很长时期的新网球冠军"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"环绕；围绕；包围","en":"To be positioned around a place or object means to surround it or be on all sides of it. To move around a place means to go along its edge, back to your starting point.","ex":{"en":"She looked at the papers around her","cn":"她看了看四周的文件。"}},{"pos":"PREP 介词","cn":"绕过；越过","en":"If you move around a corner or obstacle, you move to the other side of it. If you look around a corner or obstacle, you look to see what is on the other side.","ex":{"en":"The photographer stopped clicking and hurried around the corner","cn":"摄影师停止按动快门，匆匆绕过拐角。"}},{"pos":"ADV 副词","cn":"朝着相反方向；向着对立面","en":"If you turn around, you turn so that you are facing in the opposite direction.","ex":{"en":"I turned around and wrote the title on the blackboard","cn":"我转过身，在黑板上写下了题目。"}},{"pos":"PREP 介词","cn":"在…四处；朝…四周","en":"If you move around a place, you travel through it, going to most of its parts. If you look around a place, you look at every part of it.","ex":{"en":"I've been walking around Moscow and the town is terribly quiet","cn":"我在莫斯科到处游逛，城里非常安静。"}},{"pos":"PREP 介词","cn":"在…地方;至…的各处","en":"If someone moves around a place, they move through various parts of that place without having any particular destination.","ex":{"en":"These days much of my time is spent weaving my way around drinks parties","cn":"这些天，我多半都是在酒会上晃悠过去的。"}},{"pos":"ADV 副词","cn":"至（某人的家拜访）","en":"If you go around to someone's house, you visit them.","ex":{"en":"She helped me unpack my things and then we went around to see the other girls.","cn":"她帮我打开行李，然后我们去看望其他女孩们。"}},{"pos":"ADV 副词","cn":"闲着；无所事事","en":"You use around in expressions such as sit around and hang around when you are saying that someone is spending time in a place and not doing anything very important.","ex":{"en":"I'm just going to be hanging around twiddling my thumbs","cn":"我只会闲呆着，什么事也不做。"}},{"pos":"ADV 副词","cn":"到别处","en":"If you move things around, you move them so that they are in different places.","ex":{"en":"Furniture in the classroom should not be changed around without warning the blind child","cn":"教室中的桌椅如需要挪动，应事先告诉这个盲童。"}},{"pos":"ADV 副词","cn":"旋转;围绕","en":"If a wheel or object turns around, it turns.","ex":{"en":"The boat started to spin around in the water.","cn":"船开始在水中打旋。"}},{"pos":"PREP 介词","cn":"在各处；遍及","en":"You use around to say that something happens in different parts of a place or area.","ex":{"en":"Police in South Africa say ten people have died in scattered violence around the country","cn":"南非警方称，在全国各地零星发生的暴力事件中，有10人死亡。"}},{"pos":"ADV 副词","cn":"在某处","en":"If someone or something is around, they exist or are present in a place.","ex":{"en":"The blackbird had a quick, wary look in case the cat was anywhere around","cn":"这只乌鸫迅速警惕地张望了一眼，以防那只猫就在附近。"}},{"pos":"PREP 介词","cn":"在…周围；在…身边","en":"The people around you are the people who you come into contact with, especially your friends and relatives, and the people you work with.","ex":{"en":"We change our behaviour by observing the behaviour of those around us","cn":"我们通过观察周围人的举止改变自己的行为。"}},{"pos":"PREP 介词","cn":"以…为中心；以…为基础","en":"If something such as a film, a discussion, or a plan is based around something, that thing is its main theme.","ex":{"en":"...the gentle comedy based around the Larkin family","cn":"根据拉金一家的故事改编的轻喜剧"}},{"pos":"ADV 副词","cn":"又;循环地;周而复始地","en":"You use around in expressions such as this time around or to come around when you are describing something that has happened before or things that happen regularly.","ex":{"en":"Senator Bentsen has declined to get involved this time around","cn":"这次本特森参议员又拒绝参与。"}},{"pos":"PREP 介词","cn":"绕…一圈","en":"When you are giving measurements, you can use around to talk about the distance along the edge of something round.","ex":{"en":"She was 40 inches around the hips.","cn":"她臀围40英寸。"}},{"pos":"ADV 副词","cn":"大约","en":"Around means approximately.","ex":{"en":"My salary was around £9,000 plus a car and expenses","cn":"我的薪水大约是9,000英镑，还有一辆车和业务经费可支配。"}},{"pos":"PREP-PHRASE 短语介词","cn":"大约","en":"Around about means approximately.","ex":{"en":"There is a Green party but it only scored around about 10 percent in the vote","cn":"虽然有一个绿党，但在选举中该党只得到了大约10%的选票。"}},{"pos":"PHRASE 短语","cn":"各方面","en":"You say all around to indicate that something affects all parts of a situation or all members of a group.","ex":{"en":"He compared the achievements of the British and the French during 1916 and concluded that the latter were better all around.","cn":"他比较了1916年英国人和法国人的成就，结论是法国人在各方面都做得更好。"}},{"pos":"PHRASE 短语","cn":"见过世面；经验丰富；老于世故","en":"If someone has been around, they have had a lot of experience of different people and situations.","ex":{"en":"He knows what to do. He's been around","cn":"他知道该做什么。他阅历很丰富。"}},{"pos":"","cn":"","en":"the other way around→see: ; →see: ; →see: ;"}]},"examples":[{"en":"She's been around as a film director since the 1980s.","cn":"自 20 世纪 80 年代以来她一直是活跃在影坛的著名导演。"},{"en":"This is our new office — Kay will show you around.","cn":"这是我们的新办公室，凯会带你参观一下。"}]},"area":{"media":{"uk":"media/uk/area__gb_1.mp3","us":"media/us/area__us_1.mp3"},"oxford":{"phon":"ˈeəriə","pos":"noun","senses":[{"en":"part of a place, town, etc., or a region of a country or the world","cn":"（地方、城市、国家、世界的）地区，地域","g":"[countable]","sc":"part of place","ex":{"en":"to improve access to services in rural areas","cn":"改善农村地区获得服务的便利程度"}},{"en":"a part of a room, building or particular space that is used for a special purpose","cn":"（房间、建筑物、处所划为某用途的）地方，场地，区","g":"[countable]","sc":"part of place","ex":{"en":"the hotel reception area","cn":"旅馆接待处"}},{"en":"a particular place on an object","cn":"（物体上的）区，部位","g":"[countable]","sc":"particular place","ex":{"en":"The treatment targets the affected areas of the brain.","cn":"这个治疗针对大脑的患病部位。"}},{"en":"a particular subject or activity, or an aspect of it","cn":"领域；方面","g":"[countable]","sc":"subject/activity","ex":{"en":"Finance is Mark's area.","cn":"财务是马克负责的范围。"}},{"en":"the amount of space covered by a flat surface or piece of land, described as a measurement","cn":"面积","g":"[countable, uncountable]","sc":"measurement","ex":{"en":"the area of a triangle","cn":"三角形的面积"}},{"en":"the area in front of the goal. If the defending team breaks the rules within this area, the other team is given a penalty.","cn":"罚球区；禁区","g":"[singular]","lab":"both British English","sc":"football","ex":{"en":"He shot from just outside the area.","cn":"他就在禁区外边拔脚射门。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"地区;区域","en":"An area is a particular part of a town, a country, a region, or the world.","ex":{"en":"...the large number of community groups in the area","cn":"该地区大量的社团"}},{"pos":"N-COUNT 可数名词","cn":"（生活、管辖的）范围，区域","en":"Your area is the part of a town, country, or region where you live. An organization's area is the part of a town, country, or region that it is responsible for.","ex":{"en":"Local authorities have been responsible for the running of schools in their areas","cn":"地方当局一直负责管理本地区的学校。"}},{"pos":"N-COUNT 可数名词","cn":"（作特殊用途的）地方，场地，区","en":"A particular area is a piece of land or part of a building that is used for a particular activity.","ex":{"en":"...a picnic area.","cn":"野餐区"}},{"pos":"N-COUNT 可数名词","cn":"（某一表面或物体上的）区；（身体上的）部分","en":"An area is a particular place on a surface or object, for example on your body.","ex":{"en":"You will notice that your baby has two soft areas on the top of his head.","cn":"你会注意到你的宝宝头顶上有两处柔软的地方。"}},{"pos":"N-VAR 可变名词","cn":"面积","en":"The area of a surface such as a piece of land is the amount of flat space or ground that it covers, measured in square units.","ex":{"en":"The islands cover a total area of 625.6 square kilometers","cn":"这些岛屿总面积为625.6平方公里。"}},{"pos":"N-COUNT 可数名词","cn":"领域；方面；范围","en":"You can use area to refer to a particular subject or topic, or to a particular part of a larger, more general situation or activity.","ex":{"en":"...the politically sensitive area of old age pensions.","cn":"有关养老金的政治敏感话题"}},{"pos":"N-COUNT 可数名词","cn":"（足球场上）同penalty area","en":"On a football pitch, the area is the same as the penalty area."}]},"examples":[{"en":"The big growth area of recent years has been in health clubs.","cn":"健身俱乐部是近年来发展迅速的领域。"},{"en":"Wreckage from the plane was scattered over a wide area.","cn":"飞机失事残骸散落在一个广阔地域。"}]},"aren't":{"media":{"uk":"media/uk/aren_t_1_gb_1.mp3","us":"media/us/aren_t_1_us_2.mp3"},"oxford":{"phon":"ɑːnt","pos":"short form","senses":[{"en":"are not","cn":""},{"en":"( in questions","cn":"用于疑问句 ) am not"}]},"collins":{"senses":[{"pos":"","cn":"(are not 的常用口语形式）","en":"Aren't is the usual spoken form of 'are not'."},{"pos":"","cn":"（am not的口语形式，用于疑问句或附加问句中）","en":"Aren't is the form of 'am not' that is used in questions or tags in spoken English."}]},"examples":[{"en":"Aren't I clever?","cn":"难道我不聪明吗？"},{"en":"I’m in big trouble, aren’t I?","cn":""}]},"argumentative":{"media":{"uk":"media/uk/argumentative__gb_1.mp3","us":"media/us/argumentative__us_1.mp3"},"oxford":{"phon":"ˌɑːɡjuˈmentətɪv","pos":"adjective","senses":[{"en":"a person who is argumentative likes arguing or often starts arguing","cn":"好争论的；爱辩论的","ex":{"en":"Everyone in the family was argumentative.","cn":"家里的每个人都在争论。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"好辩的;好争论的;好争吵的","en":"Someone who is argumentative is always ready to disagree or start quarrelling with other people.","ex":{"en":"Great chess players have a reputation for being both eccentric and argumentative","cn":"国际象棋大师们以性格怪异和好与人争辩而闻名。"}}]},"examples":[{"en":"He quickly becomes argumentative after a few drinks.","cn":"他只要几杯酒下肚﹐马上就会和别人争论起来。"}]},"arduous":{"media":{"uk":"media/uk/arduous__gb_1.mp3","us":"media/us/arduous__us_1.mp3"},"oxford":{"phon":"ˈɑːdʒuəs","pos":"adjective","senses":[{"en":"involving a lot of effort and energy, especially over a period of time","cn":"艰苦的；艰难的","ex":{"en":"an arduous journey across the Andes","cn":"翻越安第斯山脉的艰苦之行"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"困难的；艰巨的；费力的","en":"Something that is arduous is difficult and tiring, and involves a lot of effort.","ex":{"en":"...a long, hot and arduous journey","cn":"一段漫长、炎热而又艰苦的旅程"}}]},"examples":[{"en":"an arduous journey across the Andes","cn":"翻越安第斯山脉的艰苦之行"},{"en":"The work was arduous.","cn":"这项工作很艰巨。"}]},"arrives":{"oxford":{"phon":"əˈraɪv","pos":"verb","senses":[{"en":"to get to a place, especially at the end of a journey","cn":"到达；抵达"},{"en":"to be brought to sb","cn":"送达；寄到"}]},"media":{"uk":"media/uk/arrive__gb_1.mp3","us":"media/us/arrive__us_1.mp3"}},"architect":{"media":{"uk":"media/uk/architect__gb_1.mp3","us":"media/us/architect__us_1.mp3"},"oxford":{"phon":"ˈɑːkɪtekt","pos":"noun","senses":[{"en":"a person whose job is designing buildings","cn":"建筑师","ex":{"en":"The house was designed by architect Louis Kahn.","cn":"这座房子是由建筑师路易斯·卡恩设计的。"}},{"en":"a person who is responsible for planning or creating an idea, an event or a situation","cn":"设计师；缔造者；创造者","ex":{"en":"He was one of the principal architects of the revolution.","cn":"他是那次革命的主要发动者之一。"}},{"en":"a person who designs or puts together a program or computer system","cn":"架构师","lab":"computing","ex":{"en":"We are looking for an IT data architect to work within our Systems Architecture team.","cn":"我们正在寻找一名 IT 数据架构师在我们的系统架构团队中工作。"}},{"en":"to design or put together a program or computer system","cn":"进行架构设计","ex":{"en":"We are looking for someone with experience of architecting data and designing databases.","cn":"我们正在寻找具有构建数据和设计数据库经验的人员。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"建筑师;设计师","en":"An architect is a person who designs buildings."},{"pos":"N-COUNT 可数名词","cn":"（景观美化、铁路等大型项目的）规划者，设计者","en":"You can use architect to refer to a person who plans large projects such as landscaping or railways.","ex":{"en":"...Merrick Denton-Thompson, the landscape architect for Hampshire county council.","cn":"梅里克·登顿-汤普森，汉普郡议会的园林设计师"}},{"pos":"N-COUNT 可数名词","cn":"（想法、事件或组织的）发起者，创立者","en":"The architect of an idea, event, or institution is the person who invented it or made it happen.","ex":{"en":"...Russia's chief architect of economic reform.","cn":"俄罗斯经济改革的总规划师"}}]},"examples":[{"en":"He was one of the principal architects of the revolution.","cn":"他是那次革命的主要发动者之一。"},{"en":"Jones was the architect of the team's first goal.","cn":"琼斯是球队入第一球的发动者。"}]},"arranges":{"oxford":{"phon":"əˈreɪndʒ","pos":"verb","senses":[{"en":"to plan or organize sth in advance","cn":"安排；筹备"},{"en":"to put sth in a particular order; to make sth neat or attractive","cn":"整理；排列；布置"}]}},"arguably":{"media":{"uk":"media/uk/arguably__gb_1.mp3","us":"media/us/arguably__us_1.mp3"},"oxford":{"phon":"ˈɑːɡjuəbli","pos":"adverb","senses":[{"en":"used (often before a comparative or superlative adjective) when you are stating an opinion that you believe you could give reasons to support","cn":"（常用于形容词比较级或最高级前）可论证地，按理","ex":{"en":"He is arguably the best actor of his generation.","cn":"按理他是他那一代中最优秀的演员。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"可论证地;可以说;按理说","en":"You can use arguably when you are stating your opinion or belief, as a way of giving more authority to it.","ex":{"en":"They are arguably the most important band since The Rolling Stones","cn":"他们无疑是继滚石之后最出色的乐队。"}}]},"examples":[{"en":"He is arguably the best actor of his generation.","cn":"按理他是他那一代中最优秀的演员。"},{"en":"Senna was arguably the greatest racing driver of all time.","cn":"可以说﹐塞纳是有史以来最伟大的赛车手。"}]},"arduously":{"oxford":{"phon":"ˈɑːdʒuəsli","pos":"adverb","senses":[{"en":"in a way that involves a lot of effort and energy, especially over a period of time","cn":"艰苦的；艰难的","ex":{"en":"They searched arduously for clues.","cn":"他们费尽心思寻找线索。"}}]},"media":{"uk":"media/uk/arduously__gb_1.mp3","us":"media/us/arduously__us_1.mp3"}},"archeology":{"oxford":{"phon":"ˌɑːkiˈɒlədʒi","pos":"noun","senses":[{"en":"the study of cultures of the past, and of periods of history by examining the parts of buildings and objects found in the ground","cn":"考古学"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41archeology.mp3","us":"media/ldoce/hwd/ame/1/archaeology__archeology.mp3"},"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"arguments":{"oxford":{"phon":"ˈɑːɡjumənt","pos":"noun","senses":[{"en":"a conversation or discussion in which two or more people disagree, often angrily","cn":"争论；争吵；争辩；辩论"},{"en":"a reason or set of reasons that sb uses to show that sth is true or correct","cn":"论据；理由；论点"}]}},"artists":{"oxford":{"phon":"ˈɑːtɪst","pos":"noun","senses":[{"en":"a person who creates works of art, especially paintings or drawings","cn":"艺术家；（尤指）画家"},{"en":"a professional entertainer such as a singer, a dancer or an actor","cn":"专业演员；艺人"}]}},"argued":{"oxford":{"phon":"ˈɑːɡjuː","pos":"verb","senses":[{"en":"to speak angrily to sb because you disagree with them","cn":"争论；争吵；争辩"},{"en":"to give reasons why you think that sth is right/wrong, true/not true, etc., especially to persuade people that you are right","cn":"论证；说理；争辩"}]}},"arrivals":{"oxford":{"phon":"əˈraɪvl","pos":"noun","senses":[{"en":"an act of coming or being brought to a place","cn":"到达；抵达"},{"en":"a person or thing that comes to a place","cn":"到达者；抵达物"}]}},"aryans":{"oxford":{"phon":"ˈeəriən","pos":"noun","senses":[{"en":"a member of the group of people that went to S Asia in around 1500 BC","cn":"雅利安人（公元前 1 500 年前后到南亚）"},{"en":"a person who spoke any of the languages of the Indo-European group","cn":"讲印欧系语言的人"}]}},"arises":{"oxford":{"phon":"əˈraɪz","pos":"verb","senses":[{"en":"to happen; to start to exist","cn":"发生；产生；出现"},{"en":"( rather formal ) to happen as a result of a particular situation （","cn":"由 … ）引起；（因 … ）产生"}]}},"armchairs":{"oxford":{"phon":"ˈɑːmtʃeə(r)","pos":"noun","senses":[{"en":"a comfortable chair with sides on which you can rest your arms","cn":"扶手椅"},{"en":"knowing about a subject through books and television, rather than by doing it for yourself","cn":"书本知识的；只说而没有行动的"}]}},"articulating":{"oxford":{"phon":"ɑːˈtɪkjuleɪt","pos":"verb","senses":[{"en":"( formal ) to express or explain your thoughts or feelings clearly in words","cn":"明确表达；清楚说明"},{"en":"to speak, pronounce or play sth in a clear way","cn":"口齿清楚；清晰吐（词）；清晰发（音）"}]}},"architects":{"oxford":{"phon":"ˈɑːkɪtekt","pos":"noun","senses":[{"en":"a person whose job is designing buildings, etc.","cn":"建筑师"},{"en":"a person who is responsible for planning or creating an idea, an event or a situation","cn":"设计师；缔造者；创造者"}]}},"arrived":{"oxford":{"phon":"əˈraɪv","pos":"verb","senses":[{"en":"to get to a place, especially at the end of a journey","cn":"到达；抵达"},{"en":"to be brought to sb","cn":"送达；寄到"}]}},"articles":{"oxford":{"phon":"ˈɑːtɪkl","pos":"noun","senses":[{"en":"a piece of writing about a particular subject in a newspaper or magazine （","cn":"报刊上的）文章，论文，报道"},{"en":"( law","cn":"律 ) a separate item in an agreement or a contract （协议、契约的）条款，项"}]}},"arriving":{"oxford":{"phon":"əˈraɪv","pos":"verb","senses":[{"en":"to get to a place, especially at the end of a journey","cn":"到达；抵达"},{"en":"to be brought to sb","cn":"送达；寄到"}]}},"archaeologists":{"oxford":{"phon":"ˌɑːkiˈɒlədʒɪst","pos":"noun","senses":[{"en":"a person who studies archaeology","cn":"考古学家"}]}},"areas":{"oxford":{"phon":"ˈeəriə","pos":"noun","senses":[{"en":"part of a place, town, etc., or a region of a country or the world （","cn":"地方、城市、国家、世界的）地区，地域"},{"en":"a part of a room, building or particular space that is used for a special purpose （","cn":"房间、建筑物、处所划为某用途的）地方，场地，区"}]}},"argues":{"oxford":{"phon":"ˈɑːɡjuː","pos":"verb","senses":[{"en":"to speak angrily to sb because you disagree with them","cn":"争论；争吵；争辩"},{"en":"to give reasons why you think that sth is right/wrong, true/not true, etc., especially to persuade people that you are right","cn":"论证；说理；争辩"}]}},"aroused":{"oxford":{"phon":"əˈraʊz","pos":"verb","senses":[{"en":"to make sb have a particular feeling or attitude","cn":"激起，引起（感情、态度）"},{"en":"to make sb feel sexually excited","cn":"激起性欲"}]}},"arousing":{"oxford":{"phon":"əˈraʊz","pos":"verb","senses":[{"en":"to make sb have a particular feeling or attitude","cn":"激起，引起（感情、态度）"},{"en":"to make sb feel sexually excited","cn":"激起性欲"}]}},"arisen":{"oxford":{"phon":"əˈraɪz","pos":"verb","senses":[{"en":"to happen; to start to exist","cn":"发生；产生；出现"},{"en":"( rather formal ) to happen as a result of a particular situation （","cn":"由 … ）引起；（因 … ）产生"}]}},"arbitration":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"仲裁；公断","en":"Arbitration is the judging of a dispute between people or groups by someone who is not involved.","ex":{"en":"...the independent arbitration service, ACAS","cn":"独立的仲裁部门，咨询调解仲裁处"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if someone, especially a lawyer, adjudicates , they officially form a judgement about who is legally right in an argument or disagreement","cn":""},{"en":"to officially judge how an argument between two opposing groups or organizations can be settled","cn":""},{"en":"the process of judging officially who is right in an argument or disagreement, by someone who has been chosen by the opposing groups","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When an uninvolved, impartial person is called in to help settle a dispute, it's called arbitration . The person in charge of the arbitration acts like an official referee, helping both sides come to an agreement."}]},"collocations":{"phrases":["ADJ. binding Both sides have agreed that the arbitration will be binding. | independent, international","VERB + ARBITRATION agree to, go to, refer sth to, submit (sth) to, take sth to Both parties agreed to independent arbitration. The matter wi","ARBITRATION + NOUN procedure, scheme, service, system"]},"media":{"uk":"media/ldoce/hwd/bre/e/arbitration0205.mp3","us":"media/ldoce/hwd/ame/1/arbitration.mp3"},"examples":[{"en":"Both sides in the dispute have agreed to go to arbitration.","cn":"争执双方已同意提请仲裁。"},{"en":"The dispute is going to arbitration (= someone is being asked to arbitrate ) .","cn":"这场争议将提请仲裁。"}],"oxford":{"phon":"ˌɑːbɪˈtreɪʃn","pos":"noun","senses":[{"en":"the official process of settling an argument or a disagreement by somebody who is not involved","cn":"仲裁；公断","ex":{"en":"Both sides in the dispute have agreed to go to arbitration.","cn":"争执双方已同意提请仲裁。"}}]}},"arise":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发生；出现","en":"If a situation or problem arises, it begins to exist or people start to become aware of it.","ex":{"en":"...if a problem arises later in the pregnancy","cn":"如果在怀孕后期出现问题"}},{"pos":"VERB 动词","cn":"（由…）产生，引起","en":"If something arises from a particular situation, or arises out of it, it is created or caused by the situation.","ex":{"en":"...an overwhelming sense of guilt arising from my actions","cn":"我的行为带来的沉重的罪恶感"}},{"pos":"VERB 动词","cn":"形成;产生;成立","en":"If something such as a new species, organization, or system arises, it begins to exist and develop.","ex":{"en":"Heavy Metal music really arose in the late 60s.","cn":"重金属音乐真正形成于60年代后期。"}},{"pos":"VERB 动词","cn":"起床","en":"When you arise, you get out of bed in the morning.","ex":{"en":"He arose at 6:30 a.m. as usual.","cn":"同往常一样，他在早上6:30起了床。"}},{"pos":"VERB 动词","cn":"起立;起身;站起","en":"When you arise from a sitting or kneeling position, you stand up.","ex":{"en":"When I arose from the chair, my father and Eleanor's father were in deep conversation","cn":"当我从椅子上站起来时，我父亲和埃莉诺的父亲谈兴正浓。"}},{"pos":"VERB 动词","cn":"呈现;矗立;耸立","en":"You can say that something tall such as a building or mountain arises from the ground around it.","ex":{"en":"...the flat terrace, from which arises the cubic volume of the house.","cn":"上面矗立着立方形房屋的露天平台"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"used especially when talking about events that have not been planned","cn":""},{"en":"to happen – used especially when talking about events that have been planned or that have already happened","cn":""},{"en":"to happen – used especially when talking about events that have not been planned","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"Arise is a verb that means to get up, maybe to stand or get out of bed, like when you arise in the morning to get ready for the day."}]},"collocations":{"phrases":["ADV. naturally, spontaneously | directly","VERB + ARISE may, might | be likely/unlikely to","PREP. from Some learning difficulties arise from the way children are taught at school. | out of The current debate arose out of the concern"]},"media":{"uk":"media/ldoce/hwd/bre/3/arise_las3_br.mp3","us":"media/ldoce/hwd/ame/5/arise.mp3"},"examples":[{"en":"Emotional or mental problems can arise from a physical cause.","cn":"身体上的原因可以引起情绪或精神上的问题。"},{"en":"Are there any matters arising from the minutes of the last meeting?","cn":"根据上次会议记录，有没有什么新情况出现？"}],"oxford":{"phon":"əˈraɪz","pos":"verb","senses":[{"en":"to happen; to start to exist","cn":"发生；产生；出现","g":"[intransitive]","lab":"rather formal","ex":{"en":"An opportunity arose to work in the United States.","cn":"出现了一次在美国工作的机会。"}},{"en":"to happen as a result of a particular situation","cn":"（由…）引起；（因…）产生","g":"[intransitive]","lab":"rather formal","ex":{"en":"injuries arising out of a road accident","cn":"道路交通事故造成的伤害"}},{"en":"to begin to exist or develop","cn":"出现；产生；发展","g":"[intransitive]","lab":"formal","ex":{"en":"Several new industries arose in the town.","cn":"城里出现了好几种新行业。"}},{"en":"to get out of bed; to stand up","cn":"起床；起立；起身","g":"[intransitive]","lab":"old use or literary","ex":{"en":"He arose at dawn.","cn":"他黎明即起。"}},{"en":"to come together to protest about something or to fight for something","cn":"群起反对；奋起斗争","g":"[intransitive]","lab":"old use","ex":{"en":"The peasants arose against their masters.","cn":"农民奋起反对奴役他们的人。"}},{"en":"to gradually start to be seen as you move towards it","cn":"（随着人走近而）逐渐出现在眼前","g":"[intransitive]","lab":"literary"}]}},"armoured":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（车辆）装甲的，装钢板的","en":"Armoured vehicles are fitted with a hard metal covering in order to protect them from gunfire and other missiles.","ex":{"en":"More than forty armoured vehicles carrying troops have been sent into the area.","cn":"载着部队官兵的40多辆装甲车被派往该地区。"}},{"pos":"ADJ 形容词","cn":"（部队）装甲的，配备装甲车辆的","en":"Armoured troops are troops in armoured vehicles.","ex":{"en":"These front-line defences are backed up by armoured units in reserve.","cn":"前线的防务得到后备装甲部队的支援。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"armoured vehicles have an outside layer made of metal to protect them from attack 〔","cn":"车辆〕装甲的"},{"en":"an armoured army uses armoured vehicles 〔","cn":"军队〕配备装甲车辆的"}]},"collocations":{"phrases":["VERBS be","ADV. heavily a convoy of heavily armoured vehicles | lightly | fully a horse capable of carrying a fully armoured knight"]},"media":{"uk":"media/ldoce/hwd/bre/4/ld44armoured.mp3","us":"media/ldoce/hwd/ame/4/ld44armoured.mp3"},"examples":[{"en":"The cruiser was heavily armoured.","cn":"这艘巡洋舰有坚固的装甲。"},{"en":"an armoured car","cn":"装甲车"}],"oxford":{"phon":"ˈɑːməd","pos":"adjective","senses":[{"en":"protected by metal covers","cn":"有装甲的","ex":{"en":"The cruiser was heavily armoured.","cn":"这艘巡洋舰有坚固的装甲。"}},{"en":"using armoured vehicles","cn":"使用装甲交通工具的","ex":{"en":"an armoured division","cn":"装甲师"}}]}},"arson":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"纵火（罪）；放火（罪）","en":"Arson is the crime of deliberately setting fire to a building or vehicle.","ex":{"en":"...a terrible wave of rioting, theft and arson","cn":"可怕的骚乱、盗窃和纵火事件接连发生"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the crime of deliberately setting fire to a building","cn":""},{"en":"the crime of deliberately damaging things, especially public property","cn":""},{"en":"to deliberately make a fire start burning, especially in order to provide heat or to cook something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you deliberately light logs on fire to roast marshmallows, you have camping skills. If you deliberately set your whole house on fire to collect the insurance money, you've committed arson ."}]},"collocations":{"phrases":["ADJ. attempted","ARSON + NOUN attack • Note at CRIME (for verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/7/arson0205.mp3","us":"media/ldoce/hwd/ame/3/arson.mp3"},"examples":[{"en":"to carry out an arson attack","cn":"进行纵火袭击"},{"en":"The school was destroyed in an arson attack .","cn":"那所学校毁于一次纵火袭击。"}],"oxford":{"phon":"ˈɑːsn","pos":"noun","senses":[{"en":"the crime of deliberately setting fire to something, especially a building","cn":"纵火（罪）；放火（罪）","lab":"British English","ex":{"en":"to carry out an arson attack","cn":"进行纵火袭击"}}]}},"armistice":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"停战，休战（协定）","en":"An armistice is an agreement between countries who are at war with one another to stop fighting and to discuss ways of making peace.","ex":{"en":"Finally, the Bolsheviks signed an armistice with Germany.","cn":"最终布尔什维克和德国签署了停战协议。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which there is no war or fighting","cn":""},{"en":"an agreement to stop fighting or arguing with each other for a limited period of time","cn":""},{"en":"an agreement to stop fighting for a limited period of time, especially in order to discuss making peace","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When two sides of a war need a break from killing each other, they agree to an armistice , a temporary battle timeout. An armistice isn’t permanent, but it’s usually a sign that both sides want to give peace a chance."}]},"collocations":{"phrases":["VERB + ARMISTICE ask for, call for, seek | negotiate, work out | agree to, sign","PREP. ~ with to sign an armistice with the Americans"]},"media":{"uk":"media/ldoce/hwd/bre/c/armistice_las3_br.mp3","us":"media/ldoce/hwd/ame/8/armistice.mp3"},"oxford":{"phon":"ˈɑːmɪstɪs","pos":"noun","senses":[{"en":"a formal agreement during a war to stop fighting and discuss making peace","cn":"休战；停战；休战条约；停战协定","ex":{"en":"The armistice was signed on 4 December.","cn":"停战协定于12月4日签署。"}}]}},"artillery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"火炮；大炮","en":"Artillery consists of large, powerful guns which are transported on wheels and used by an army.","ex":{"en":"Using tanks and heavy artillery, they seized the town.","cn":"他们倚仗坦克和重型火炮占领了这个镇。"}},{"pos":"N-SING-COLL 单数集合名词","cn":"炮兵（部队）","en":"The artillery is the section of an army which is trained to use large, powerful guns.","ex":{"en":"At some stage he left the Artillery to command a radar unit.","cn":"有段时间他离开了炮兵部队去指挥一支雷达小分队。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"large guns, either on wheels or fixed in one place","cn":"炮﹐大炮"},{"en":"the part of the army that uses these weapons","cn":"炮兵部队"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Artillery refers to large-caliber guns — guns with big barrels — which can be moved from one place to another for land battles. The artillery is also the name for the army unit that uses these big guns."}]},"collocations":{"phrases":["ADJ. field | heavy The enemy has enough heavy artillery to win the war.","ARTILLERY + NOUN attack, barrage, bombardment, fire | piece, shell | train, unit The soldiers of the artillery train had panicked and cut th"]},"media":{"uk":"media/ldoce/hwd/bre/c/artillery0205.mp3","us":"media/ldoce/hwd/ame/c/artillery.mp3"},"examples":[{"en":"The town is under heavy artillery fire.","cn":"该市镇处于密集的炮火之下。"}],"oxford":{"phon":"ɑːˈtɪləri","pos":"noun","senses":[{"en":"large, heavy guns which are often moved on wheels","cn":"（统称）火炮","g":"[uncountable]","ex":{"en":"The town is under heavy artillery fire.","cn":"该市镇处于密集的炮火之下。"}},{"en":"the section of an army trained to use these guns","cn":"炮兵部队","g":"[singular]","ex":{"en":"He was a captain in the Royal Artillery.","cn":"他是皇家炮兵的上尉。"}}]}},"arrears":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"应付欠款；（尤指）逾期债款","en":"Arrears are amounts of money that you owe, especially regular payments that you should have made earlier.","ex":{"en":"They have promised to pay the arrears over the next five years","cn":"他们保证在随后的5年内偿付逾期债款。"}},{"pos":"PHRASE 短语","cn":"拖欠（付款）","en":"If someone is in arrears with their payments, or has got into arrears, they have not paid the regular amounts of money that they should have paid.","ex":{"en":"...the 300,000 households who are more than six months in arrears with their mortgages.","cn":"拖欠抵押贷款超过6个月的30万户家庭"}},{"pos":"PHRASE 短语","cn":"（工资等）后付的","en":"If sums of money such as wages or taxes are paid in arrears, they are paid at the end of the period of time to which they relate, for example after a job has been done and the wages have been earned.","ex":{"en":"Unemployment benefit is paid fortnightly in arrears.","cn":"失业救济金延后两个星期支付。"}},{"pos":"PHRASE 短语","cn":"（体育比赛中成绩或比分）落后的","en":"If someone is in arrears in a sports match or race, they are not winning, because they have a lower score or slower time than other competitors.","ex":{"en":"Davies finished almost two seconds in arrears for third place.","cn":"戴维斯落后了差不多两秒，获得第三名。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"use this about payments that should have been made or library books that should have been returned before now","cn":""},{"en":"to have not made one or more regular payments at the time when you should","cn":""},{"en":"to have not made one or more regular payments at the time when you should","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you are in arrears, you are behind in the payment of a debt. Think: rears=behind. Arrears also refers to the unpaid, overdue debt itself. Your rent arrears are the money you own on rent."}]},"collocations":{"phrases":["ADJ. debt, mortgage, rent, tax","VERB + ARREARS fall into, get into, owe They fell into arrears with their rent. The government has agreed to pay all arrears owed to members","ARREARS + VERB amount to sth, total sth By this time the arrears amounted to &pound; 12,000.","PREP. in ~ She was six months in arrears with the mortgage. You will be paid monthly in arrears. | ~ on There have been sharp increases in a"]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdearrears.mp3","us":"media/ldoce/hwd/ame/b/arrears.mp3"},"examples":[{"en":"We're two months in arrears with the rent.","cn":"我们拖欠了两个月的租金。"},{"en":"rent/mortgage/tax arrears","cn":"拖欠租金/按揭贷款/税款"}],"oxford":{"phon":"əˈrɪəz","pos":"noun","senses":[{"en":"money that somebody owes that they have not paid at the right time","cn":"逾期欠款","ex":{"en":"rent/mortgage/tax arrears","cn":"拖欠租金／按揭贷款／税款"}}]}},"arthritis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"关节炎","en":"Arthritis is a medical condition in which the joints in someone's body are swollen and painful.","ex":{"en":"I have a touch of arthritis in the wrist.","cn":"我的手腕患有轻微关节炎。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a disease that causes the joints of your body to become swollen and very painful","cn":"关节炎"}]},"vocab":{"pos":"n","senses":[{"en":"Arthritis is a painful condition in which your joints swell and stiffen. It is common in older people, although it can affect anyone, including athletes who've injured knees, ankles, and hips."}]},"collocations":{"phrases":["ADJ. severe | chronic | rheumatoid","VERB + ARTHRITIS have, suffer (from) | develop, get It is unclear why some people develop arthritis. | treat","ARTHRITIS + NOUN sufferer","PHRASES crippled with arthritis •"]},"media":{"uk":"media/ldoce/hwd/bre/2/arthritis_las3_br.mp3","us":"media/ldoce/hwd/ame/d/arthritis.mp3"},"oxford":{"phon":"ɑːˈθraɪtɪs","pos":"noun","senses":[{"en":"a disease that causes one or more joints of the body to become painful and swollen (= larger than normal)","cn":"关节炎","ex":{"en":"It is unclear why some people develop arthritis.","cn":"尚不明确为什么有些人会得关节炎。"}}]}},"arbitrary":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"武断的;任意的;任性的;主观的","en":"If you describe an action, rule, or decision as arbitrary, you think that it is not based on any principle, plan, or system. It often seems unfair because of this.","ex":{"en":"Arbitrary arrests and detention without trial were common.","cn":"随意逮捕和拘留屡见不鲜。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you do or choose things at random , you do or choose them without using any plan or system","cn":""},{"en":"something that is random is done or chosen without using any plan or system","cn":""},{"en":"something that is arbitrary is decided or arranged without any reason, plan, or system, especially in a way that seems unfair","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's arbitrary seems like it's chosen at random instead of following a consistent rule. Team members would dislike their coach using a totally arbitrary method to pick starting players."}]},"collocations":{"phrases":["VERBS be, seem","ADV. completely, entirely, purely, quite, wholly | fairly, rather, somewhat, to some extent The decision is to some extent arbitrary. | esse"]},"media":{"uk":"media/ldoce/hwd/bre/a/arbitrary0205.mp3","us":"media/ldoce/hwd/ame/a/arbitrary.mp3"},"examples":[{"en":"The choice of players for the team seemed completely arbitrary.","cn":"看来这个队的队员完全是随意选定的。"},{"en":"He makes unpredictable, arbitrary decisions.","cn":"他做的决定难以预料，主观武断。"}],"oxford":{"phon":"ˈɑːbɪtrəri","pos":"adjective","senses":[{"en":"not seeming to be based on a reason, system or plan and sometimes seeming unfair","cn":"任意的；武断的；随心所欲的","ex":{"en":"The choice of players for the team seemed completely arbitrary.","cn":"看来这个队的队员完全是随意选定的。"}},{"en":"using power without limits and without considering other people","cn":"专横的；专制的","lab":"formal","ex":{"en":"the arbitrary powers of officials","cn":"官员的专制权力"}}]}},"armchair":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"扶手椅","en":"An armchair is a big comfortable chair which has a support on each side for your arms.","ex":{"en":"She was sitting in an armchair with blankets wrapped round her.","cn":"她坐在扶手椅中，身上裹着毯子。"}},{"pos":"ADJ 形容词","cn":"（通过阅读或倾听）间接了解的，非亲身经历的","en":"An armchair critic, fan, or traveller knows about a particular subject from reading or hearing about it rather than from practical experience.","ex":{"en":"The last thing we need are words of wisdom from an armchair critic","cn":"我们最不需要的是纸上谈兵的评论家发表的“智慧”言论。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a comfortable chair with sides that you can rest your arms on","cn":"扶手椅"},{"en":"to deliberately not take part in something, because you disagree with it or think it is wrong","cn":""},{"en":"to decide not to take part in a competition, race, discussion etc, which you previously agreed to take part in","cn":""}]},"collocations":{"phrases":["ADJ. big, deep, large | comfortable, comfy | battered, old, worn | leather, upholstered, wicker, wooden","VERB + ARMCHAIR be seated in, be slumped in, be sprawled in, sit in | collapse into, flop into, throw yourself into | curl up in, ease yours"]},"media":{"img":["media/ldoce/img/armchair.jpg"],"uk":"media/ldoce/hwd/bre/5/armchair_n0205.mp3","us":"media/ldoce/hwd/ame/8/l3armchair.mp3"},"examples":[{"en":"an armchair critic/traveller","cn":"不切实际的批评家；端坐家中的神游旅行者"},{"en":"to sit in an armchair","cn":"坐在扶手椅上"}],"oxford":{"phon":"ˈɑːmtʃeə(r)","pos":"noun","senses":[{"en":"a comfortable chair with sides on which you can rest your arms","cn":"扶手椅；单人沙发","ex":{"en":"to sit in an armchair","cn":"坐在扶手椅上"}},{"en":"knowing about a subject through books, television, the internet, etc., rather than by doing it for yourself","cn":"纸上谈兵的","ex":{"en":"an armchair critic/traveller","cn":"不切实际的批评家；端坐家中的神游旅行者"},"pos":"adjective"}]}},"aroma":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（食物等的）香味，芳香","en":"An aroma is a strong, pleasant smell.","ex":{"en":"...the wonderful aroma of freshly baked bread.","cn":"新鲜出炉的面包散发出的美妙香味"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you can recognize by breathing in through your nose","cn":""},{"en":"something that you smell for a short time","cn":""},{"en":"a smell – used especially about the pleasant smell from flowers, plants, or fruit. Also used about the smell left by an animal","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Aroma is the word for a fragrant scent, one that pleases the nose in a way that makes you lick your lips. Unlike its foul-smelling cousin the odor, an aroma smells but never stinks."}]},"collocations":{"phrases":["ADJ. pungent, rich, strong | distinctive | lingering | faint, subtle | pleasant, sweet, wonderful | appetizing, mouth-watering","VERB + AROMA savour, smell As soon as I opened the front door I smelled the distinctive aroma of fresh coffee. | be filled with, have The ro","AROMA + VERB linger, waft Th e aroma of fresh baking wafte d towards her ."]},"media":{"uk":"media/ldoce/hwd/bre/8/aroma0205.mp3","us":"media/ldoce/hwd/ame/c/aroma.mp3"},"examples":[{"en":"the aroma of fresh coffee","cn":"新鲜咖啡的香味"}],"oxford":{"phon":"əˈrəʊmə","pos":"noun","senses":[{"en":"a pleasant smell that is easy to notice","cn":"芳香；香味","ex":{"en":"the aroma of fresh coffee","cn":"新鲜咖啡的香味"}}]}},"articulate":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"善于表达的;口齿伶俐的","en":"If you describe someone as articulate, you mean that they are able to express their thoughts and ideas easily and well.","ex":{"en":"She is an articulate young woman","cn":"她是一个口才很好的年轻女子。"}},{"pos":"VERB 动词","cn":"清楚地表达（思想或感情）","en":"When you articulate your ideas or feelings, you express them clearly in words.","ex":{"en":"The president has been accused of failing to articulate an overall vision in foreign affairs.","cn":"总统因未能清晰表述对外交事务的整体构想而受到指责。"}},{"pos":"VERB 动词","cn":"清楚地说出；吐（字）清楚","en":"If you articulate something, you say it very clearly, so that each word or syllable can be heard.","ex":{"en":"He articulated each syllable carefully.","cn":"他小心而清晰地发出每个音节。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to express your ideas or feelings in words","cn":"清楚地表达"},{"en":"to pronounce what you are saying in a clear and careful way","cn":"口齿清楚地讲（话）﹔清晰发（音）"},{"en":"if something such as a bone in your body is articulated to another thing, it is joined to it in a way that allows movement","cn":"连接﹐铰接"}]},"vocab":{"pos":"1 v adj 2 adj v","senses":[{"en":"To articulate is to say something. And, if you say it well, someone might praise you by saying you are articulate . Confused yet? It's all in the pronunciation."}]},"collocations":{"phrases":["VERBS be | become","ADV. highly, very a highly articulate woman","PREP. about The teachers help the children to be more articulate about their strengths and weaknesses."]},"media":{"uk":"media/ldoce/hwd/bre/7/articulate_v0205.mp3","us":"media/ldoce/hwd/ame/f/l3articulate2.mp3"},"examples":[{"en":"All we could hear were loud sobs, but no articulate words.","cn":"我们听到的只是大声啜泣，没有清楚的话语。"},{"en":"Every note was carefully articulated.","cn":"每个音都唱得很认真，很清楚。"}],"oxford":{"phon":"ɑːˈtɪkjuleɪt","pos":"verb","senses":[{"en":"to express or explain your thoughts or feelings clearly in words","cn":"明确表达；清楚说明","g":"[transitive]","lab":"formal","ex":{"en":"She struggled to articulate her thoughts.","cn":"她竭力表明她的想法。"}},{"en":"to speak, pronounce or play something in a clear way","cn":"口齿清楚；清晰吐（词）；清晰发（音）","g":"[intransitive, transitive]","ex":{"en":"He was too drunk to articulate properly.","cn":"他醉得连话都说不清楚。"}},{"en":"to be related to something so that together the two parts form a whole","cn":"与…合成整体","g":"[intransitive]","lab":"formal","ex":{"en":"These courses are designed to articulate with university degrees.","cn":"这些课程旨在与大学学位接轨。"}},{"en":"to be joined to something else by a joint, so that movement is possible; to join something in this way","cn":"用关节连接；链合；铰接","g":"[intransitive, transitive]","lab":"specialist","ex":{"en":"bones that articulate with others","cn":"与其他骨骼以关节相连的骨骼"}},{"en":"good at expressing ideas or feelings clearly in words","cn":"善于表达的","ex":{"en":"He was unusually articulate for a ten-year-old.","cn":"对于一个十岁的孩子来说，他的表达能力非同一般。"},"pos":"adjective"},{"en":"clearly expressed or pronounced","cn":"口齿清楚的；发音清晰的","ex":{"en":"All we could hear were loud sobs, but no articulate words.","cn":"我们听到的只是大声啜泣，没有清楚的话语。"},"pos":"adjective"}]}},"arizona":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a state in the southwest of the US, north of Mexico that has a large area of desert. Arizona is popular with tourists, many of whom come to see the Grand Canyon.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/p028-000001710.mp3","us":"media/ldoce/hwd/ame/4/p028-000001710.mp3"},"oxford":{"phon":"ˌærɪˈzəʊnə","pos":"","senses":[{"en":"a state in the south-western US, also known as the Grand Canyon State. Its capital and largest city is Phoenix. Arizona's natural features include the Grand Canyon, the Painted Desert and the Petrified Forest. It was the home of the Apache people in the 19th century, and today there are 20 reservations (= areas of land kept for native North American people to live on) in the state. Its most important industry is manufacturing, especially of electrical and communication equipment. It also produces a large percentage of the country's copper.","cn":"亚利桑那（美国西南部的州，首府和最大城市菲尼克斯，特色自然景观包括大峡谷）"}]}},"arabic":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"阿拉伯语","en":"Arabic is a language that is spoken in the Middle East and in parts of North Africa."},{"pos":"ADJ 形容词","cn":"阿拉伯语的；阿拉伯文字的；阿拉伯文化的","en":"Something that is Arabic belongs or relates to the language, writing, or culture of the Arabs.","ex":{"en":"...a large tapestry with swirling Arabic script.","cn":"绘有螺旋形阿拉伯字母的大幅花毯"}},{"pos":"ADJ 形容词","cn":"（数字）阿拉伯的","en":"An Arabic numeral is one of the written figures such as 1, 2, 3, or 4.","ex":{"en":"The clock is available with either Roman or Arabic numerals.","cn":"这款钟有带罗马数字的，也有带阿拉伯数字的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the language or writing of the Arabs, which is the main language of North Africa and the Middle East","cn":"阿拉伯语"}]},"collocations":{"phrases":["ADJ. classical, modern","ARABIC + NOUN script • Note at LANGUAGE"]},"media":{"uk":"media/ldoce/hwd/bre/1/arabic0205.mp3","us":"media/ldoce/hwd/ame/d/arabic.mp3"},"examples":[{"en":"Arabic poetry","cn":"阿拉伯诗歌"}],"oxford":{"phon":"ˈærəbɪk","pos":"noun","senses":[{"en":"the language of the Arabs","cn":"阿拉伯语"},{"en":"of or connected with the literature and language of Arab people","cn":"阿拉伯文学的；阿拉伯语的","ex":{"en":"Arabic poetry","cn":"阿拉伯诗歌"},"pos":"adjective"}]}},"artery":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"动脉","en":"Arteries are the tubes in your body that carry blood from your heart to the rest of your body.","ex":{"en":"...patients suffering from blocked arteries.","cn":"患动脉栓塞的病人"}},{"pos":"N-COUNT 可数名词","cn":"主干路；干线；要道","en":"You can refer to an important main route within a complex road, railway, or river system as an artery .","ex":{"en":"Clarence Street was one of the northbound arteries of the central business district.","cn":"克拉伦斯街是中央商业区北段部分的主干路之一。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the tubes that carries blood from your heart to the rest of your body","cn":"动脉"},{"en":"a main road, railway line, river etc","cn":"干道﹔干线﹔干流"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"An artery is a major blood vessel that pumps blood away from your heart. For a healthy heart, keep your arteries clean!"}]},"collocations":{"phrases":["ADJ. main, major | blocked, clogged | severed | carotid, coronary, pulmonary, etc.","VERB + ARTERY block | widen The surgeon will widen her arteries. | rupture, sever","ARTERY + VERB clog up Too much fatty food will make your arteries more likely to clog up.","PHRASES hardening of the arteries (= a disease of the arteries) She suffers from hardening of the arteries. | veins and arteries blood flowi"]},"media":{"img":["media/ldoce/img/body.jpg"],"uk":"media/ldoce/hwd/bre/2/artery0205.mp3","us":"media/ldoce/hwd/ame/8/artery.mp3"},"examples":[{"en":"blocked arteries","cn":"堵塞的动脉"},{"en":"arterial blood/disease","cn":"动脉血/病"}],"oxford":{"phon":"ˈɑːtəri","pos":"noun","senses":[{"en":"any of the tubes that carry blood from the heart to other parts of the body","cn":"动脉","lab":"British English","ex":{"en":"blocked arteries","cn":"堵塞的动脉"}},{"en":"a large and important road, river, railway line, etc.","cn":"干线（指主要的公路、河流、铁路线等）"}]}}});
